/*===========================================================================

FUNCTION cmph_set_is_user_resel_buffered_ss

DESCRIPTION
  Set the value to is_user_resel_buffered flag for ss

DEPENDENCIES
  none

RETURN VALUE
  none

SIDE EFFECTS
  None

===========================================================================*/
static void cmph_set_is_user_resel_buffered_ss(

  sys_modem_as_id_e_type            asubs_id,
  /* value that needs to be set to is_user_resel_buffered per SS */
  boolean                 val
)
{
  cmph_sub_info_s_type *ph_sub_ptr = cmph_get_sub_ptr(asubs_id);
  CM_MSG_MED_2( "is_user_resel_buffered set %d for subs %d", val, asubs_id );
  if (ph_sub_ptr)
  {
    ph_sub_ptr->is_user_resel_buffered = val;
  }
}

/*===========================================================================

FUNCTION cmph_get_is_user_resel_buffered_ss

DESCRIPTION
 Get the value for is_user_resel_buffered flag for ss

DEPENDENCIES
  none

RETURN VALUE
  boolean

SIDE EFFECTS
  None

===========================================================================*/
static boolean cmph_get_is_user_resel_buffered_ss(

  sys_modem_as_id_e_type            asubs_id
)
{
  cmph_sub_info_s_type *ph_sub_ptr = cmph_get_sub_ptr(asubs_id);
  if (ph_sub_ptr)
  {
    return ph_sub_ptr->is_user_resel_buffered;
  }
  return FALSE;

} /* cmph_get_is_user_resel_buffered_ss */

/*===========================================================================

FUNCTION  cmph_is_srv_domain_changed_ps_attach_detach_during_volte_call

DESCRIPTION
 Utility function which checks if there is a VOLTE call active and srv_domain_pref
 changed to PS Attach/detach on a particular SUB

DEPENDENCIES
 cmph_init has been called.

RETURN VALUE
  TRUE or FALSE

SIDE EFFECTS
  none

===========================================================================*/
boolean    cmph_is_srv_domain_changed_ps_attach_detach_during_volte_call(
  sys_modem_as_id_e_type  asubs_id,
  cm_srv_domain_pref_e_type  srv_domain_pref
)
{
  boolean result = FALSE;

  if(cmcall_is_active_audio_call_per_sub(asubs_id) && (srv_domain_pref == CM_SRV_DOMAIN_PREF_PS_DETACH) )
  {
    result = TRUE;
    CM_MSG_HIGH_3("Is srv_domain_pref=%d rcvd during wifi call on asubs_id=%d, result = %d",
                  srv_domain_pref, asubs_id, result);
  }

  else if(cmcall_is_active_audio_call_per_sub_except_wlan(asubs_id) &&
          (srv_domain_pref == CM_SRV_DOMAIN_PREF_PS_DETACH ||
           srv_domain_pref == CM_SRV_DOMAIN_PREF_PS_ATTACH )
         )
  {
    result = TRUE;
    CM_MSG_HIGH_3("Is srv_domain_pref=%d rcvd during VOLTE call on asubs_id=%d, result = %d",
                  srv_domain_pref, asubs_id, result);
  }
  return result;
}
/*===========================================================================

FUNCTION  cmph_get_feature_mode

DESCRIPTION
 Get the current feature mode configuration stored in phone object.

DEPENDENCIES
 None

RETURN VALUE
  feature_mode

SIDE EFFECTS
  None

===========================================================================*/
sys_overall_feature_t  cmph_get_feature_mode (void)
{
  sys_overall_feature_t feature_mode = cmph_ptr()->device_prop.feature_mode;

  if (cmph_is_ssim() &&
      feature_mode != SYS_OVERALL_FEATURE_MODE_SVLTE &&
      feature_mode != SYS_OVERALL_FEATURE_MODE_SRLTE)
  {
    feature_mode = SYS_OVERALL_FEATURE_MODE_NORMAL;
  }
  return feature_mode;
}

/*===========================================================================

FUNCTION  cmph_is_feature_mode_1x_sxlte

DESCRIPTION
 The function returns if the overall feature mode configuration is svlte/srlte.

DEPENDENCIES
 none

RETURN VALUE
  TRUE if feature mode is svlte/srlte.
  FALSE otherwise.

SIDE EFFECTS
  none

===========================================================================*/
boolean  cmph_is_feature_mode_1x_sxlte (void)
{
  sys_overall_feature_t feature_mode = cmph_get_feature_mode();
  return (feature_mode == SYS_OVERALL_FEATURE_MODE_SVLTE ||
          feature_mode == SYS_OVERALL_FEATURE_MODE_SRLTE);
}

/*===========================================================================

FUNCTION  cmph_get_subs_feature_mode

DESCRIPTION
 Get the current sub feature mode configuration stored in phone object.

DEPENDENCIES
 None

RETURN VALUE
  feature_mode

SIDE EFFECTS
  None

===========================================================================*/
sys_subs_feature_t  cmph_get_subs_feature_mode (sys_modem_as_id_e_type  asubs_id)
{
  cmph_sub_info_s_type *ph_sub_ptr = cmph_get_sub_ptr(asubs_id);
  if (ph_sub_ptr)
  {
    return (ph_sub_ptr->subs_feature_mode);
  }
  else
  {
    CM_ERR_1("Subs_feature requested for invalid as_id %d",asubs_id);
    return SYS_SUBS_FEATURE_MODE_NORMAL;
  }
}

