/*===========================================================================

FUNCTION cmph_notify_mmoc_no_sim

DESCRIPTION
  After an emergency call has ended, we must notify MMOC the
  SIM is missing or failed.

DEPENDENCIES
  none

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
void cmph_notify_mmoc_no_sim (

  sys_modem_as_id_e_type asubs_id
  /* sub on which the emergency call has ended */
)
{
  cmph_s_type  *ph_ptr = cmph_ptr();
  sys_manual_sys_info_s_type  sys_id;
  mmoc_subs_data_s_type       *sub_data;
  cmph_sub_info_s_type *ph_sub_ptr = cmph_get_sub_ptr(asubs_id);

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* Validate nam */
  if (!BETWEEN((int)ph_ptr->device_prop.curr_nam, (int)CM_NAM_NONE, (int)NV_MAX_NAMS))
  {
    CM_ERR_1( "invalid nam: %d", ph_ptr->device_prop.curr_nam);
    return;
  }

  if (ph_sub_ptr == NULL) return;

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
  /* Get the persistance preferences of this SS */

  sub_data = (mmoc_subs_data_s_type *)cm_mem_malloc(sizeof(mmoc_subs_data_s_type));
  if (sub_data == NULL) return;

  sub_data->as_id           = asubs_id;
  sub_data->mode_pref       = SD_GET_COMMON_MODE(
                                cmph_map_cm_mode_pref_to_sd_mode_pref(
                                  CMPH_PRST_SS_MODE_PREF( asubs_id, ph_ptr)),
                                cmmsc_get_stk_mode_cap(
                                  cmph_map_sub_stk_to_id(asubs_id, MM_STACK_0)));
  sub_data->band_pref       = cmutil_map_cm_band_pref_to_sd_band_pref(
                                CMPH_PRST_SS_BAND_PREF(asubs_id,ph_ptr));
  /*sub_data->tds_band_pref   = cmutil_map_cm_tds_band_pref_to_sd_tds_band_pref(
                                      CMPH_PRST_SS_TDS_BAND_PREF(asubs_id,ph_ptr));*/
  sub_data->tds_band_pref   = SD_SS_BAND_PREF_TDS_EMPTY;
  /*sub_data->lte_band_pref   = CMPH_PRST_SS_LTE_BAND_PREF(asubs_id,ph_ptr);*/
  sub_data->lte_band_pref   = SYS_LTE_BAND_MASK_CONST_NONE;
  /*sub_data->hybr_pref       = cmutil_map_cm_hybr_pref_to_sd_hybr_pref(
                                          CMPH_PRST_SS_HYBR_PREF(asubs_id,ph_ptr));*/
  sub_data->hybr_pref       = SD_SS_HYBR_PREF_NONE;
  sub_data->prl_pref        = cmutil_map_cm_prl_pref_to_sd_prl_pref(
                                CMPH_PRST_SS_PRL_PREF(asubs_id,ph_ptr));
  sub_data->orig_mode       = cmutil_map_cm_network_sel_mode_pref_to_orig_mode(
                                CMPH_PRST_SS_NETWORK_SEL_MODE_PREF( asubs_id, ph_ptr ));
  sub_data->acq_order_pref  = cmutil_map_cm_acq_order_pref_to_sd(
                                CMPH_PRST_SS_ACQ_ORDER_PREF( asubs_id, ph_ptr ));
  sub_data->srv_domain_pref = cmutil_map_cm_srv_domain_pref_to_sd(
                                CMPH_PRST_SS_SRV_DOMAIN_PREF( asubs_id, ph_ptr));
  sub_data->roam_pref       = cmutil_map_cm_roam_pref_to_sd_roam_pref(
                                CMPH_PRST_SS_ROAM_PREF(asubs_id,ph_ptr));
  sub_data->voice_domain_pref = *(CMPH_SS_VOICE_DOMAIN_PREF_PTR(asubs_id, cmph_ptr()));

  sub_data->nv_context      = (uint16)asubs_id;
  sys_id.sys_id.id_type  = SYS_SYS_ID_TYPE_UMTS;
  sys_id.sys_id.id.plmn     = ph_sub_ptr->pref_info.plmn;
  sys_id.prm.gw.sel_type = SYS_MANUAL_SEL_TYPE_USER_SPECIFIED;

  sub_data->manual_sys_info = sys_id;
  sub_data->is_perso_locked = FALSE;

  if(!cmpmprx_is_ok_to_enforce_device_policy(CM_CALL_ID_INVALID))
  {
    sub_data->subs_capability = cmmsc_get_curr_msc_max_cap(asubs_id);
  }
  else
  {
    sub_data->subs_capability = cmpmprx_fetch_max_mode_capability(asubs_id);
  }

  sub_data->sub_avail       = 0;
  sub_data->prot_subsc_chg  = PROT_SUBSC_CHG_ALL;
  sub_data->active_stacks   = MM_STACK_0_MASK;

  sub_data->gpp_session_type  = AS_ID_TO_GW_SESSION(asubs_id);
  sub_data->gpp2_session_type = AS_ID_TO_1X_SESSION(asubs_id);

  /* ADD_PROTO with both CDMA and GW makes both protocol stacks reload
  ** NV information
  */
  mmoc_cmd_subscription_chgd_new( MMOC_SUBSC_CHG_SUBSC_AVAIL,
                                  (byte) ph_ptr->device_prop.curr_nam,
                                  BM(asubs_id),
                                  cmmsimc_state_ptr()->dev_info.standby_pref,
                                  cmpmprx_get_device_mode(),
                                  PROT_SUBSC_CHG_ALL,
                                  PROT_SUBSC_CHG_NONE,
                                  PROT_SUBSC_CHG_NONE,
                                  sub_data,
                                  NULL,
                                  NULL
                                );
  cm_mem_free (sub_data);
} /* cmph_notify_mmoc_no_sim */

/*===========================================================================
FUNCTION cmph_load_prst_phone_pref_on_main

DESCRIPTION
  updates the ph_ptr with persistent values from NV on main stack


DEPENDENCIES
  Phone object must have already been initialized with
  cmph_init().

RETURN VALUE
  None

SIDE EFFECTS
  None

===========================================================================*/
static void                     cmph_load_prst_phone_pref_on_sub(

  sys_modem_as_id_e_type   asubs_id,

  cm_ph_cmd_s_type          *ph_cmd_ptr
)
{
  cmph_s_type     *ph_ptr = cmph_ptr();
  uint8            i = 0;
  cm_pref_s_type  *pref_ptr = NULL;
  cm_pref_s_type  *prst_pref_ptr = NULL;

  cm_sys_sel_pref_params_s_type *pmprx_pref_ptr = NULL;
  cmph_sub_info_s_type *ph_sub_ptr = cmph_get_sub_ptr(asubs_id);
  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  if (!cmutil_is_as_id_valid(asubs_id) || ph_sub_ptr == NULL)
  {
    CM_MSG_HIGH_1("Attempting load prst on invalid sub %d",asubs_id);
    return;
  }
  pref_ptr = &ph_sub_ptr->pref_info;
  prst_pref_ptr = &ph_sub_ptr->prst_pref_info[ ph_ptr->device_prop.curr_nam ];
  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
  /* Reload perstistant values on ONLINE and subscription */

  pref_ptr->mode_pref              = prst_pref_ptr->mode_pref;
  pref_ptr->user_mode_pref         = prst_pref_ptr->mode_pref;
  pref_ptr->band_pref              = prst_pref_ptr->band_pref;
  pref_ptr->lte_band_pref          = prst_pref_ptr->lte_band_pref;
  pref_ptr->tds_band_pref          = prst_pref_ptr->tds_band_pref;
  pref_ptr->prl_pref               = prst_pref_ptr->prl_pref;
  pref_ptr->roam_pref              = prst_pref_ptr->roam_pref;
  pref_ptr->hybr_pref              = prst_pref_ptr->hybr_pref;
  pref_ptr->acq_order_pref         = prst_pref_ptr->acq_order_pref;
  pref_ptr->network_sel_mode_pref  = prst_pref_ptr->network_sel_mode_pref;

  ph_sub_ptr->sub_3gpp2_pref.int_hybr_pref = cmutil_map_cm_hybr_pref_to_sd_hybr_pref(pref_ptr->hybr_pref);

  if(ph_ptr->device_prop.msim_prop.default_data_subs == asubs_id)
  {
    pref_ptr->srv_domain_pref = prst_pref_ptr->srv_domain_pref;
    ph_sub_ptr->ps_pref.is_ps_srv_req_sent = TRUE;
  }
  else
  {
    if( prst_pref_ptr->srv_domain_pref == CM_SRV_DOMAIN_PREF_PS_ONLY  ||
        prst_pref_ptr->srv_domain_pref == CM_SRV_DOMAIN_PREF_NONE
      )
    {
      pref_ptr->srv_domain_pref = CM_SRV_DOMAIN_PREF_NONE;
    }
    else
    {
      pref_ptr->srv_domain_pref = CM_SRV_DOMAIN_PREF_CS_ONLY;
    }
  }

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
  /** This is required for Release-7 and beyond. */
  if ( prst_pref_ptr->user_net_sel_mode == CM_USER_NETWORK_SEL_MODE_PREF_AUTOMATIC
       ||
       prst_pref_ptr->user_net_sel_mode == CM_USER_NETWORK_SEL_MODE_PREF_MANUAL )
  {
    pref_ptr->network_sel_mode_pref =
      cmph_map_user_to_cm_net_sel_mode_pref ( prst_pref_ptr->user_net_sel_mode);
  }

  /* If target support 3gpp2 and 3gpp and manual network select command is
  ** issued 3gpp2 RATs should be removed and compute new mode pref.
  */
  if ( sd_misc_is_target_supp_mode_band (SD_SS_MODE_PREF_CDMA_HDR,
                                         SD_SS_BAND_PREF_ANY,
                                         SYS_LTE_BAND_MASK_CONST_NONE,
                                         SD_SS_BAND_PREF_NONE)
       && pref_ptr->network_sel_mode_pref == CM_NETWORK_SEL_MODE_PREF_MANUAL
       && is_contain_3GPP_mode_pref(pref_ptr->mode_pref) )
  {

    pref_ptr->user_mode_pref = pref_ptr->mode_pref;
    pref_ptr->mode_pref =
      cm_remove_mode_pref_components(pref_ptr->mode_pref,
                                     2,
                                     SD_SS_MODE_PREF_CDMA_HDR,
                                     SD_SS_MODE_PREF_GPS
                                    );
    
  }

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
#ifdef FEATURE_CM_LTE
  // Reset Rat Disable Mask
  ph_sub_ptr->rat_disabled_mask = 0;

  if(pref_ptr->srv_domain_pref == CM_SRV_DOMAIN_PREF_CS_ONLY)
  {
    cm_mode_pref_e_type new_mode_pref;
    if(!cmph_is_dual_lte())
    {
      new_mode_pref = cm_remove_mode_pref_components( pref_ptr->mode_pref,
                      1,
                      SD_SS_MODE_PREF_LTE);
      if(SD_MODE_CONTAIN(cmph_map_cm_mode_pref_to_sd_mode_pref(pref_ptr->mode_pref),SD_SS_MODE_PREF_LTE) &&
          !SD_MODE_CONTAIN(cmph_map_cm_mode_pref_to_sd_mode_pref(new_mode_pref),SD_SS_MODE_PREF_LTE))
      {
        pref_ptr->mode_pref = new_mode_pref;
        cmph_rat_disabled_mask_add( SYS_SYS_MODE_LTE,asubs_id);
      }
    }
  }
#endif

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - */
  /* Call into Policy manager and retrieve new policy if needed.
  */
  pmprx_pref_ptr = (cm_sys_sel_pref_params_s_type *)
                   cm_mem_malloc(sizeof(cm_sys_sel_pref_params_s_type));
  pmprx_pref_ptr->mode_pref          = pref_ptr->mode_pref;
  pmprx_pref_ptr->term_pref          = pref_ptr->pref_term;
  pmprx_pref_ptr->pref_duration    = 0;
  pmprx_pref_ptr->band_pref          = pref_ptr->band_pref;
  pmprx_pref_ptr->lte_band_pref      = pref_ptr->lte_band_pref;
  pmprx_pref_ptr->tds_band_pref      = pref_ptr->tds_band_pref;
  pmprx_pref_ptr->prl_pref           = pref_ptr->prl_pref;
  pmprx_pref_ptr->roam_pref          = pref_ptr->roam_pref;
  pmprx_pref_ptr->hybr_pref          = pref_ptr->hybr_pref;
  pmprx_pref_ptr->srv_domain_pref    = pref_ptr->srv_domain_pref;
  pmprx_pref_ptr->plmn_ptr           = &( pref_ptr->plmn );
  pmprx_pref_ptr->csg_id             = pref_ptr->csg_id ;
  pmprx_pref_ptr->csg_rat            = pref_ptr->csg_rat;
  pmprx_pref_ptr->ue_usage_setting   = pref_ptr->ue_usage_setting;
  pmprx_pref_ptr->voice_domain_pref  = pref_ptr->voice_domain_pref;
  pmprx_pref_ptr->lte_disable_cause  = CM_LTE_DISABLE_CAUSE_NO_CHANGE;
  pmprx_pref_ptr->volte_enable_state = CM_VOLTE_NO_CHANGE;
  pmprx_pref_ptr->is_allow_buffering_cmd = FALSE;
  pmprx_pref_ptr->network_sel_mode_pref = pref_ptr->network_sel_mode_pref;

  cmpmprx_sys_sel_pref_policy_update( asubs_id,pmprx_pref_ptr,ph_cmd_ptr);

  cm_mem_free(pmprx_pref_ptr);

#ifdef FEATURE_RAT_PRIORITY_LIST
  /* Read RAT acquisition order from PM
  */
  if(!cmpmprx_get_rat_acq_order_pref(asubs_id,
                                     &ph_sub_ptr->rat_acq_order_pref))
  {
    CM_MSG_HIGH_1("LOAD_PRST: Fail to get rat_acq_order (TOT) for sub %d from PM", i);
  }
#else
  /* If rat priority list is not defind, fill the default value
  */
  ph_sub_ptr->rat_acq_order_pref.num_rat = 0;
#endif

  /* reset dds_switch_pending flag on oprt_mode change or subsc change */
  if(asubs_id == ph_ptr->device_prop.msim_prop.default_data_subs)
  {
    ph_ptr->device_prop.msim_prop.dds_switch_pending = FALSE;
  }

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - */

  CM_MSG_HIGH_6_ASID_EXT("LOAD_PRST: prst mode_pref %d, mode_pref %d, hybr_pref %d, srv_domain %d network_sel_mode_pref %d",
                         asubs_id,
                         prst_pref_ptr->mode_pref,
                         pref_ptr->mode_pref,
                         pref_ptr->hybr_pref,
                         pref_ptr->srv_domain_pref,
                         pref_ptr->network_sel_mode_pref,
                         (asubs_id+1));

} /* cmph_load_prst_phone_pref_on_sub() */

/*===========================================================================
FUNCTION cmph_load_prst_phone_pref

DESCRIPTION
  updates the ph_ptr with persistent values from NV


DEPENDENCIES
  Phone object must have already been initialized with
  cmph_init().

RETURN VALUE
  None

SIDE EFFECTS
  None

===========================================================================*/
static void cmph_load_prst_phone_pref ( cm_ph_cmd_s_type          *ph_cmd_ptr )
{
  sys_modem_as_id_e_type asubs_id = SYS_MODEM_AS_ID_1;
  cmph_load_prst_dual_standby_pref();

  for (asubs_id = SYS_MODEM_AS_ID_1; cmutil_is_as_id_valid(asubs_id); asubs_id ++)
  {
    cmph_load_prst_phone_pref_on_sub(asubs_id,ph_cmd_ptr);
  }
}

