/*===========================================================================

FUNCTION cmph_process_network_list_cnf

DESCRIPTION
  This function processes a network list confirmation event reported
  by the lower software layer.


DEPENDENCIES
  Phone object must have already been initialized with cmph_init().

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
static void cmph_process_network_list_cnf
(
  const cm_rpt_type             *cm_rpt_ptr
  /* Pointer to lower level report data */
)
{
  /* Pointer to phone object.
  */
  cmph_s_type                *ph_ptr = cmph_ptr();
  const cm_si_network_list_cnf_s_type   *net_list_cnf_ptr = NULL;
  mm_sub_stk_id_s_type mm_id;
  dword                    uptime = time_get_uptime_secs();
  cm_orig_q_s_type        *ph_orig_top_ptr;
  cmmsc_proc_cmd_pref_sys_chgd_s_type  cmd;
  cmph_sub_info_s_type *ph_sub_ptr, *ph_net_sub_ptr;
  boolean is_pfscan = FALSE, clear_pf_scan_info = TRUE;
  uint32 list_length = 0;

  /* - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - */

  CM_ASSERT(cm_rpt_ptr != NULL);

  /* - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - */

  net_list_cnf_ptr = &cm_rpt_ptr->cmd.si_net_list_cnf;

  /* networks_type was added to delay ps call when there
  ** is a get net request pending. This flag need not be checked before
  ** sending NETWORKS_CONF event to clients. Any time SD sends a net list
  ** cnf, CM sends the corresp client event out.
  **
  ** In cases where SD gives back an acq action and posts a net list cnf,
  ** net list cnf would not get posted to CM clients because acq action
  ** will clear network_type flag, that's why removing network_type check.
  */
  memset(&mm_id, 0, sizeof(mm_sub_stk_id_s_type));
  
  if (cmph_is_msim())
  {
    mm_id.asubs_id = cm_rpt_ptr->asubs_id;
  }
  else
  {
    mm_id.asubs_id = SYS_MODEM_AS_ID_1;
  }

  ph_sub_ptr = cmph_get_sub_ptr(mm_id.asubs_id);
  ph_net_sub_ptr = cmph_get_net_sub_ptr(mm_id.asubs_id);
  
  if(!cmutil_is_as_id_valid(mm_id.asubs_id) || 
     ph_sub_ptr == NULL ||
     ph_net_sub_ptr == NULL)
  {
    return;
  }

  is_pfscan = (cmutil_is_periodic_manual_search() &&
               ph_ptr->device_prop.pf_scan_info &&
               ph_ptr->device_prop.pf_scan_info->asubs_id == mm_id.asubs_id &&
               cmph_is_get_networks_ongoing(mm_id.asubs_id) &&
               ph_net_sub_ptr->pref_info.network_list_type != CM_NETWORK_LIST_CSG &&
               ph_net_sub_ptr->pref_info.network_list_type != CM_NETWORK_LIST_CSG_SELECTION_APP &&
               ph_net_sub_ptr->pref_info.network_list_type != CM_NETWORK_LIST_CSG_USER &&
              !ph_net_sub_ptr->pref_info.ignore_manual_bst);

  ph_net_sub_ptr->pref_info.network_list_cnf = net_list_cnf_ptr->status;

  if(ph_net_sub_ptr->pref_info.network_list_type == CM_NETWORK_LIST_PCI_SCAN )
  {
    ph_sub_ptr->plmn_list.pci_plmn_list = net_list_cnf_ptr->found_plmn_list.pci_plmn_list;
    list_length = ph_sub_ptr->plmn_list.pci_plmn_list.num_cell;
  }
  else
  {
    ph_sub_ptr->plmn_list.plmn_list = net_list_cnf_ptr->found_plmn_list.plmn_list;
    list_length = ph_sub_ptr->plmn_list.plmn_list.length;
  }

  CM_MSG_HIGH_6_ASID("GET_NET: LIST_CNF: network_type %d, status %d, network_list_type %d, list_length %d, is_pfscan %d",
                mm_id.asubs_id,
                ph_net_sub_ptr->pref_info.network_type,
                net_list_cnf_ptr->status,
                ph_net_sub_ptr->pref_info.network_list_type,
                list_length,
                is_pfscan);  

  /* - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - */

  /* Periodic search handling
  */
  if(is_pfscan)
    {
    if (!ph_ptr->device_prop.pf_scan_info) {return;}

    /* Success with length 0 means an attempt completed but returned no results
    */
    if(net_list_cnf_ptr->status == SYS_PLMN_LIST_SUCCESS &&
       list_length == 0)
    {
      // Increment num attempts
      ph_ptr->device_prop.pf_scan_info->attempts ++;

      // If max attempts is reached, terminate the search
      if(ph_ptr->device_prop.pf_scan_info->attempts >= CM_INQUISITIVE_SEARCH_NUM_ATTEMPTS_MAX)
      {
        CM_MSG_HIGH_6("GET_NET: LIST_CNF: PERIODIC: reached max attempts, terminate srch, periodicity %d, priority %d, attempts %d, uptime %d, next_uptime %d, max_uptime %d",
                          ph_ptr->device_prop.pf_scan_info->search_periodicity,
                          ph_ptr->device_prop.pf_scan_info->priority,
                          ph_ptr->device_prop.pf_scan_info->attempts,
                          uptime,
                          ph_ptr->device_prop.pf_scan_info->next_uptime,
                          ph_ptr->device_prop.pf_scan_info->max_uptime);

        cmph_event_per_subs(CM_PH_EVENT_AVAILABLE_NETWORKS_CONF, mm_id.asubs_id);
  }

      /* High priority - it was the last attempt or one-timer srch, cm needs to terminate the srch */
      else if(ph_ptr->device_prop.pf_scan_info->priority == SYS_SRCH_PRIORITY_HIGH)
      {
        CM_MSG_HIGH_6("GET_NET: LIST_CNF: PERIODIC: high-priority srch, terminate srch, periodicity %d, priority %d, attempts %d, uptime %d, next_uptime %d, max_uptime %d",
                          ph_ptr->device_prop.pf_scan_info->search_periodicity,
                          ph_ptr->device_prop.pf_scan_info->priority,
                          ph_ptr->device_prop.pf_scan_info->attempts,
                          uptime,
                          ph_ptr->device_prop.pf_scan_info->next_uptime,
                          ph_ptr->device_prop.pf_scan_info->max_uptime);

        cmph_event_per_subs(CM_PH_EVENT_AVAILABLE_NETWORKS_CONF, mm_id.asubs_id);
      }

      // Else we can start the timer for the next attempt
      else
  {
        clear_pf_scan_info = FALSE;
        ph_ptr->device_prop.pf_scan_info->next_uptime = uptime + ph_ptr->device_prop.pf_scan_info->search_periodicity;
        
        CM_MSG_HIGH_6("GET_NET: LIST_CNF: PERIODIC: start timer, periodicity %d, last priority %d, attempts %d, uptime %d, next_uptime %d, max_uptime %d",
                          ph_ptr->device_prop.pf_scan_info->search_periodicity,
                          ph_ptr->device_prop.pf_scan_info->priority,
                          ph_ptr->device_prop.pf_scan_info->attempts,
                          uptime,
                          ph_ptr->device_prop.pf_scan_info->next_uptime,
                          ph_ptr->device_prop.pf_scan_info->max_uptime);
  }

    }

    /* Search is successful and plmn is found - terminate the MPLMN */
    else if(net_list_cnf_ptr->status == SYS_PLMN_LIST_SUCCESS &&
          list_length > 0)
  {
      cmph_event_per_subs(CM_PH_EVENT_AVAILABLE_NETWORKS_CONF, mm_id.asubs_id);
  }

    /* When abort is received during a periodic search, do not terminate the search completely.
    ** Instead set a fast retry timer
    */
    else if(net_list_cnf_ptr->status == SYS_PLMN_LIST_AS_ABORT ||
            net_list_cnf_ptr->status == SYS_PLMN_LIST_ABORT_ON_TRM_FAILURE ||
            net_list_cnf_ptr->status == SYS_PLMN_LIST_REJ_IN_RLF)
  {
      clear_pf_scan_info = FALSE;
      ph_ptr->device_prop.pf_scan_info->next_uptime = uptime + CM_INQUISITIVE_SEARCH_FAST_RETRY_TIMER;
      
      CM_MSG_HIGH_6("GET_NET: LIST_CNF: PERIODIC: received abort, restart timer, periodicity %d, last priority %d, attempts %d, uptime %d, next_uptime %d, max_uptime %d",
                        ph_ptr->device_prop.pf_scan_info->search_periodicity,
                        ph_ptr->device_prop.pf_scan_info->priority,
                        ph_ptr->device_prop.pf_scan_info->attempts,
                        uptime,
                        ph_ptr->device_prop.pf_scan_info->next_uptime,
                        ph_ptr->device_prop.pf_scan_info->max_uptime);

      /* High priority - it was the last attempt or one-timer srch, cm needs to terminate the srch */
      if(ph_ptr->device_prop.pf_scan_info->priority == SYS_SRCH_PRIORITY_HIGH)
      {
        CM_MSG_HIGH_6("GET_NET: LIST_CNF: PERIODIC: high-priority srch, terminate srch, periodicity %d, priority %d, attempts %d, uptime %d, next_uptime %d, max_uptime %d",
                          ph_ptr->device_prop.pf_scan_info->search_periodicity,
                          ph_ptr->device_prop.pf_scan_info->priority,
                          ph_ptr->device_prop.pf_scan_info->attempts,
                          uptime,
                          ph_ptr->device_prop.pf_scan_info->next_uptime,
                          ph_ptr->device_prop.pf_scan_info->max_uptime);
        cmph_event_per_subs(CM_PH_EVENT_AVAILABLE_NETWORKS_CONF, mm_id.asubs_id);
        clear_pf_scan_info = TRUE;
  }
      /* Send event when some PLMNs are found */
      else if(list_length != 0)
  {
        ph_net_sub_ptr->pref_info.network_list_cnf = SYS_PLMN_LIST_PERIODIC_PARTIAL;                  
        cmph_event_per_subs(CM_PH_EVENT_AVAILABLE_NETWORKS_CONF, mm_id.asubs_id);
  }
    }
    else if (net_list_cnf_ptr->status == SYS_PLMN_LIST_PARTIAL)
  {
      CM_MSG_HIGH_6("GET_NET: LIST_CNF: PERIODIC: received partial result, periodicity %d, last priority %d, attempts %d, uptime %d, next_uptime %d, max_uptime %d",
                        ph_ptr->device_prop.pf_scan_info->search_periodicity,
                        ph_ptr->device_prop.pf_scan_info->priority,
                        ph_ptr->device_prop.pf_scan_info->attempts,
                        uptime,
                        ph_ptr->device_prop.pf_scan_info->next_uptime,
                        ph_ptr->device_prop.pf_scan_info->max_uptime);
      ph_net_sub_ptr->pref_info.network_list_cnf = SYS_PLMN_LIST_PERIODIC_PARTIAL;                  
      cmph_event_per_subs(CM_PH_EVENT_AVAILABLE_NETWORKS_CONF, mm_id.asubs_id);
      clear_pf_scan_info = FALSE;
    }
  }

  /* - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - */

  /* Buffer the manual search if aborted on TRM failure 
  */
  else if(net_list_cnf_ptr->status == SYS_PLMN_LIST_ABORT_ON_TRM_FAILURE)
  {
    if(cmcall_is_active_call_other_than_ss(mm_id, CM_CALL_TYPE_VOICE)     != CM_CALL_ID_INVALID ||
       cmcall_is_active_call_other_than_ss(mm_id, CM_CALL_TYPE_EMERGENCY) != CM_CALL_ID_INVALID)
    {
      ph_ptr->device_prop.man_srch_state = CM_MAN_SRCH_STATE_BUFFERED_CALL;
      ph_ptr->device_prop.man_srch_timer_uptime = uptime + CM_MAN_SRCH_CALL_TIMER;
      CM_MSG_HIGH_3("GET_NET: LIST_CNF: Buffering man srch on sub %d due to call on other sub, uptime %d man_srch_timer_uptime %d", 
                    mm_id.asubs_id, uptime, ph_ptr->device_prop.man_srch_timer_uptime);
    }
    else
    {
      ph_ptr->device_prop.man_srch_state = CM_MAN_SRCH_STATE_BUFFERED_TIMER;
      ph_ptr->device_prop.man_srch_timer_uptime = uptime + CM_MAN_SRCH_DEFAULT_TIMER;
      CM_MSG_HIGH_3("GET_NET: LIST_CNF: Buffering man srch on sub %d due to TRM failure, uptime %d man_srch_timer_uptime %d",
                     mm_id.asubs_id, uptime, ph_ptr->device_prop.man_srch_timer_uptime);
    }

    if(ph_ptr->device_prop.man_srch_max_timer_uptime == 0)
    {
      ph_ptr->device_prop.man_srch_max_timer_uptime = uptime + CM_MAN_SRCH_MAX_TIMER;
      CM_MSG_HIGH_2("GET_NET: LIST_CNF: Set man srch max timer, uptime %d max_timer_uptime %d",
                     uptime, ph_ptr->device_prop.man_srch_max_timer_uptime);
    }
    return;
  }  

  ph_ptr->device_prop.man_srch_max_timer_uptime = 0;
  ph_sub_ptr->is_net_lists_present = FALSE;

  if(!is_pfscan)
  {
  /*Send AVAILABLE NET CNF if
  1. MANUAL BST is invalid
  2. Manual BST is valid and MANUAL SEARCH TIMER is 0 - Means First User triggered Scan
  3. MANUAL BST is valid and MANUAL SEARCH TIMER is not expired - Means User Triggered Scan*/
    if(!ph_net_sub_ptr->pref_info.ignore_manual_bst)
  {
    /*User triggered MPLMN Scan. So inform to Clients*/
    cmph_event_per_subs( CM_PH_EVENT_AVAILABLE_NETWORKS_CONF, mm_id.asubs_id);
      CM_MSG_HIGH_2( "GET_NET: LIST_CNF: Send available net cnf for user manual search, Internal Manual Search timer_uptime %d uptime %d",
                     ph_ptr->device_prop.internal_manual_search_timer_uptime, uptime );
  }
    else if (ph_ptr->device_prop.internal_manual_search_timer_uptime <= uptime)
    {
      if(net_list_cnf_ptr->status == SYS_PLMN_LIST_AS_ABORT ||
           net_list_cnf_ptr->status == SYS_PLMN_LIST_REJ_IN_RLF)
      {
        /*Start Redial Timer after Internal MPLMN Scan is completed*/
        ph_ptr->device_prop.internal_manual_search_timer_uptime = time_get_uptime_secs() + CM_PERIODIC_MANUAL_SEARCH_REDIAL_TIMER;
        CM_MSG_HIGH_2( "GET_NET: LIST_CNF: Restart internal timer due to abort/reject. Internal Manual Search timer_uptime %d uptime %d",
                       ph_ptr->device_prop.internal_manual_search_timer_uptime, uptime );
      }
      else if (net_list_cnf_ptr->status == SYS_PLMN_LIST_SUCCESS)
      {
        /* Restart Timer after Internal MPLMN Scan is completed */
        ph_ptr->device_prop.internal_manual_search_timer_uptime = time_get_uptime_secs() + ph_ptr->device_prop.internal_manual_search_timer;
        CM_MSG_HIGH_2( "GET_NET: LIST_CNF: Restart internal timer due to success. Internal Manual Search timer_uptime %d uptime %d",
                       ph_ptr->device_prop.internal_manual_search_timer_uptime, uptime );
      }
    }
  }

  if (net_list_cnf_ptr->status != SYS_PLMN_LIST_PARTIAL)
  {
    cmmsc_state_machine_s_type *state_machine = NULL;
    if (cmph_is_get_networks_ongoing(mm_id.asubs_id) == TRUE)
    {
      state_machine = cmmsimc_state_machine_ptr(mm_id.asubs_id);
    }

    /* If this is not cnf for a periodic scan, but there is an existing periodic scan
    ** (being buffered), do not free pf scan info. Only reset other manual search preferences. 
    */
    if(cmutil_is_periodic_manual_search() && !is_pfscan)
    {
      cmph_reset_network_pref(mm_id.asubs_id, FALSE);
    }
    else
    {
      cmph_reset_network_pref(mm_id.asubs_id, clear_pf_scan_info);
    }

    /*Verify MAIN stack been suspended and resume on list cnf */
    #ifdef FEATURE_MMODE_SC_SVLTE
    if ( cmph_is_subs_feature_mode_1x_sxlte(mm_id.asubs_id) &&
         ph_sub_ptr->ss_susp_info[MM_STACK_0].is_suspend == TRUE)
  {
      CM_MSG_HIGH_1("CM->MMOC: GET_NET: LIST_CNF: sub %d RESUME stack0", mm_id.asubs_id);
      mmoc_cmd_suspend_stack(mm_id, FALSE, FALSE);
    }
    #endif

    /* if STACK_SYNC_UP_BSR is pending due to this network search list
    ** force pref on HYBR_2 with STACK_SYNC_UP_BSR 
    */
    if (state_machine && cmmsc_auto_is_stack_sync_bsr_pending(state_machine)) 
    {
      CM_MSG_HIGH_0("GET_NET: LIST_CNF: Restoring STACK_SYNC_UP_BSR after net_list_cnf");
      ph_orig_top_ptr = cmtask_orig_para_get_top(cmph_map_sub_stk_to_id(mm_id.asubs_id, MM_STACK_2));

    if( ph_orig_top_ptr == NULL )
    {
        CM_MSG_HIGH_1("GET_NET: LIST_CNF: stack_sync_up_bsr not forced top_ptr NULL, sub %d", mm_id.asubs_id);
      return;
    }

    cmmsc_pack_cmd_for_pref_sys_chgd_per_top_queue (
         cmph_map_sub_stk_to_id(mm_id.asubs_id,MM_STACK_2),
      SD_SS_PREF_REAS_STACK_SYNC_UP_BSR,
      SD_SS_ORIG_MODE_NONE,
      FALSE,
      ph_orig_top_ptr,
      CM_ACT_UPDATE_REAS_NONE,
      &cmd
    );

    cmmsimc_proc_cmd_pref_sys_chgd(&cmd);

    cmmsc_auto_update_is_stack_sync_bsr_pending(state_machine, FALSE);
    cmmsc_auto_update_is_kick_hybr2_pending(state_machine, FALSE);
    *cmph_get_is_kicked_hybr_2_ptr()               = TRUE;
  }

    /*Enforce any pending policies that were buffered due to ongoing PLMN search */
    cmpmprx_get_networks_end_ind();
  }
} /* cmph_process_network_list_cnf() */

