/*===========================================================================

FUNCTION  cmph_ssim_init

DESCRIPTION
 Initialize the single sim mode.

DEPENDENCIES


RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
static void cmph_ssim_init (void)
{
  cmph_s_type                    *ph_ptr = cmph_ptr();

  /* Read the Dual-standby preferences from NV
  */
  cmnv_read_wait( NV_DUAL_STANDBY_CFG_ITEMS_I, cmnv_item_ptr );
  ph_ptr->device_prop.msim_prop.user_standby_pref  = (sys_modem_dual_standby_pref_e_type)cmnv_item_ptr->dual_standby_cfg_items.dual_standby_pref;


  /* If DS pref from NV is NO_STANDBY, power up with sub DISABLED
  */
  if(ph_ptr->device_prop.msim_prop.user_standby_pref == SYS_MODEM_DS_PREF_NO_STANDBY_PREF)
  {
    ph_ptr->device_prop.msim_prop.standby_pref          = SYS_MODEM_DS_PREF_NO_STANDBY_PREF;
    ph_ptr->device_prop.msim_prop.internal_standby_pref = SYS_MODEM_DS_PREF_NO_STANDBY_PREF;
    ph_ptr->device_prop.msim_prop.new_standby_pref      = SYS_MODEM_DS_PREF_NO_STANDBY_PREF;
    ph_ptr->device_prop.msim_prop.active_subs           = SYS_MODEM_AS_ID_NO_ACTIVE_MASK;
    ph_ptr->device_prop.msim_prop.is_bootup_no_standby  = TRUE;
  }
  else
  {
    /* Internally CM treats single sim opr mode same as single standby on sub1 in dual sim
     ** opr mode
     */
    ph_ptr->device_prop.msim_prop.user_standby_pref     = SYS_MODEM_DS_PREF_SINGLE_STANDBY;
    ph_ptr->device_prop.msim_prop.standby_pref          = SYS_MODEM_DS_PREF_SINGLE_STANDBY;
    ph_ptr->device_prop.msim_prop.internal_standby_pref = SYS_MODEM_DS_PREF_SINGLE_STANDBY;
    ph_ptr->device_prop.msim_prop.new_standby_pref      = SYS_MODEM_DS_PREF_SINGLE_STANDBY;
    ph_ptr->device_prop.msim_prop.active_subs           = SYS_MODEM_AS_ID_1_MASK;
    ph_ptr->device_prop.msim_prop.is_bootup_no_standby  = FALSE;
  }

  /* For single sim opr mode, the following params should be ignored
   */
  ph_ptr->device_prop.msim_prop.priority_subs           = SYS_MODEM_AS_ID_1;
  ph_ptr->device_prop.msim_prop.curr_priority_subs      = SYS_MODEM_AS_ID_1;
  ph_ptr->device_prop.msim_prop.default_data_subs       = SYS_MODEM_AS_ID_1;
  ph_ptr->device_prop.msim_prop.default_voice_subs      = SYS_MODEM_AS_ID_1;
  ph_ptr->device_prop.msim_prop.curr_voice_subs         = SYS_MODEM_AS_ID_1;
  ph_ptr->device_prop.msim_prop.new_default_data_subs   = SYS_MODEM_AS_ID_1;

}

