/*===========================================================================

FUNCTION cmph_get_first_sub_with_lte_cap

DESCRIPTION
  Returns the sub which has LTE in max cap. This API should only be used
  when dual-LTE is disabled since it will return the first sub that has
  LTE in the max cap.

DEPENDENCIES
  None

RETURN VALUE
  sys_modem_as_id_e_type

SIDE EFFECTS
  none

===========================================================================*/
sys_modem_as_id_e_type cmph_get_first_sub_with_lte_cap(void)
{
  sys_modem_as_id_e_type as_id_val = SYS_MODEM_AS_ID_NONE;

  if (!cmph_is_msim())
  {
    return SYS_MODEM_AS_ID_1;
  }

  for(as_id_val=SYS_MODEM_AS_ID_1; cmutil_is_as_id_valid(as_id_val); as_id_val++)
  {
    if(cmph_is_lte_capable_on_sub(as_id_val))
    {
      return as_id_val;
    }
  }
  /*It should not come here*/
  CM_MSG_HIGH_0("Invalid Config: LTE cap not present in any SUB");
  return SYS_MODEM_AS_ID_1;
}

