/*===========================================================================
FUNCTION cmph_send_oprt_mode_online_to_mmoc

DESCRIPTION
    This function sends operating mode online to mmoc if it is buffered.

DEPENDENCIES

RETURN VALUE
   Void

SIDE EFFECTS
  None
===========================================================================*/

void cmph_send_oprt_mode_online_to_mmoc
(
  void
)
{
    CM_MSG_HIGH_2("CM->MMOC: oprt_mode_hold: send oprt mode to mmoc, send_time %d, oprt_mode %d",
                cmph_ptr()->device_prop.ph_oprt_mode.oprt_mode_send_time,
                cmph_ptr()->device_prop.ph_oprt_mode.oprt_mode );

  if (cmph_ptr()->device_prop.ph_oprt_mode.oprt_mode_send_time != CMPH_MAX_UPTIME)
  {
    sys_modem_as_id_e_type asubs_id;

#ifdef FEATURE_CM_DEBUG_BUFFER
    cmdbg_add_oprt_mode_cmd_to_buffer(SYS_OPRT_MODE_ONLINE);
#endif
    if (cmph_is_emerg_pending())
    {
      mmoc_cmd_oprt_mode_chgd2(
            SYS_OPRT_MODE_ONLINE,
            cmph_get_emerg_pending_info().state);
    }
    else
    {
    mmoc_cmd_oprt_mode_chgd( SYS_OPRT_MODE_ONLINE );
    }
    cmph_ptr()->device_prop.ph_oprt_mode.oprt_mode_send_time = CMPH_MAX_UPTIME;


    cmmsimc_proc_cmd_oprt_mode_chgd(SYS_OPRT_MODE_ONLINE);

    /* Reset the origination throttle table
    */
    cmss_orig_thr_table_reset();

    /* Clear the is hybr kicked flag
    */
    *cmph_get_is_kicked_hybr_ptr() = FALSE;

    for (asubs_id = SYS_MODEM_AS_ID_1; cmutil_is_as_id_valid(asubs_id); asubs_id++)
    {
      cmph_send_subs_info(asubs_id,NULL);
    }
    /* Updating clients about pref info now, to keep them in sync*/
    cmph_sp_subs_info_update();
    cmph_update_vsid_info();
    cmph_force_emerg_pending();
  }
}

