/*===========================================================================

FUNCTION cmph_update_suspend_status

DESCRIPTION
  take action whenever a new suspend cmd has been sent to MMOC or response
  has been recieved from MMOC.
  update suspend status whenver response is obtained.
  increment or decrement num_request based on request/response sent/recieved.

DEPENDENCIES
  Ph object must have already been initialized with
  cmph_init().

RETURN VALUE
  None

SIDE EFFECTS
  none

===========================================================================*/
void cmph_update_suspend_status(

  mm_sub_stk_id_s_type            mm_id,
  /* indicates the stack that is being updated
  */

  boolean                 is_request,
  /* indicate if a request has been sent (TRUE) or response recieved (FALSE)
  */

  boolean                 suspend_status
  /* valid only if is_request = FALSE (response). It is the new value of
  ** stack suspend status
  */
)
{
  cm_stack_suspend_info_s_type *info_ptr;
  cmph_sub_info_s_type *ph_sub_ptr = cmph_get_sub_ptr(mm_id.asubs_id);

  if (!cmutil_is_as_id_valid(mm_id.asubs_id) || ph_sub_ptr == NULL ||
      !(mm_id.stk_id >= MM_STACK_0 && mm_id.stk_id <= MM_STACK_2))
  {
    return;
  }

  info_ptr = &(ph_sub_ptr->ss_susp_info[mm_id.stk_id]);

  /* If a request is being sent to MMOC, update request count and indicate
  ** 1xcp */
  if( is_request )
  {
    info_ptr->num_requests++;
  }
  /* If a response is recieved, update status and decrement count
  */
  else
  {
    if( info_ptr->num_requests > 0 )
    {
      info_ptr->num_requests--;
      info_ptr->is_suspend = suspend_status;
    }
    if( suspend_status == 0 )
    {
      info_ptr->is_suspend = suspend_status;
    }
  }
  CM_MSG_HIGH_4("SO:sub %d, stk %d susp_status %d , num_req %d",mm_id.asubs_id,mm_id.stk_id,
                ph_sub_ptr->ss_susp_info[mm_id.stk_id].is_suspend,
                ph_sub_ptr->ss_susp_info[mm_id.stk_id].num_requests);
}//cmph_update_suspend_status

/*===========================================================================

FUNCTION cmph_ss_susp_due_to_emerg

DESCRIPTION
  Check iff stack is supended due to emergency

DEPENDENCIES
  Ph object must have already been initialized with
  cmph_init().

RETURN VALUE
  TRUE if stack is suspended, FALSE otherwise

SIDE EFFECTS
  none

===========================================================================*/
boolean cmph_ss_susp_due_to_emerg(

  mm_sub_stk_id_s_type            mm_id
  /* Stack to be checked */
)
{
  uint8 i;
  cmph_sub_info_s_type *ph_sub_ptr = cmph_get_sub_ptr(mm_id.asubs_id);

  if (!cmutil_is_as_id_valid(mm_id.asubs_id) || ph_sub_ptr == NULL)
  {
    return FALSE;
  }

  if (mm_id.stk_id < cmtask_get_num_stacks(mm_id.asubs_id) && mm_id.stk_id > MM_STACK_NONE )
  {
    return ph_sub_ptr->ss_susp_info[mm_id.stk_id].susp_due_to_emerg;
  }
  else /* MM_STACK_ALL */
  {
    /* CM_SS_MAX case. Need to check if any of the stacks is suspended */
    for(i=MM_STACK_0; i<cmtask_get_num_stacks(mm_id.asubs_id); i++)
    {
      if(ph_sub_ptr->ss_susp_info[i].susp_due_to_emerg)
      {
        return TRUE;
      }
    }
  }

  return FALSE;

}/* cmph_ss_susp_due_to_emerg */

/*===========================================================================

FUNCTION cmph_get_ss_mode_pref

DESCRIPTION
  Returns the mode_pref of corresponding ss

DEPENDENCIES
  Ph object must have already been initialized with
  cmph_init().

RETURN VALUE
  mode_pref of ss, which is passed as argument

SIDE EFFECTS
  none

===========================================================================*/
cm_mode_pref_e_type cmph_get_ss_mode_pref(
  sys_modem_as_id_e_type  as_id
)
{
  if (IS_VALID_PH_SUB_PTR(as_id))
  {
    return cmph_ptr()->sub_info[as_id]->pref_info.mode_pref;
  }

  return CM_MODE_PREF_NONE;
}

/*===========================================================================

FUNCTION  cmph_delete_and_unforce_activity

DESCRIPTION
 This function checks for the given activityand unforces it without any timer logic.

DEPENDENCIES
 none

RETURN VALUE
  ss

SIDE EFFECTS
  none

===========================================================================*/
void cmph_delete_and_unforce_activity(mm_sub_stk_id_s_type mm_id, cm_act_id_type  act_id)
{
  cm_orig_q_s_type  *ph_orig_ptr;
  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
  CM_MSG_MED_3("cmph_delete_and_unforce_activity sub %d, stk %d, act = %u",
               mm_id.asubs_id, mm_id.stk_id,act_id);

  /* Search the ptr
  */
  if (mm_id.stk_id == MM_STACK_NONE || !cmutil_is_as_id_valid(mm_id.asubs_id))
  {
    return;
  }

  mm_id.stk_id = (mm_id.stk_id == MM_STACK_ALL ? MM_STACK_0 : mm_id.stk_id);

  ph_orig_ptr = cmtask_orig_para_search_act_id(mm_id, act_id);

  if( ph_orig_ptr != NULL )
  {
    /* Delete the priority object identified by act_id */
    if (cmtask_orig_para_delete(mm_id, ph_orig_ptr, TRUE ))
    {
      cmph_force_orig_mode_on_the_stack(mm_id);
    }
  }
}


/*===========================================================================

FUNCTION cmph_add_mode_in_DSDX

DESCRIPTION
   To add the modes as dictated by NV-mode_disabled_in_TSTS to the mode_pref of
   multimode sub.

DEPENDENCIES
  Ph object must have already been initialized with
  cmph_init().
  standby pref should change from triple standby to dual/single standby

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
void cmph_add_mode_in_DSDX()
{

  cm_mode_pref_e_type      cm_prst_mode_pref = CM_MODE_PREF_NONE;
  cm_mode_pref_e_type      cm_mode_pref = CM_MODE_PREF_NONE;
  cmph_s_type             *ph_ptr = cmph_ptr();
  sys_modem_as_id_e_type   sub_asub_id = cmph_get_first_sub_with_lte_cap();
  cmph_sub_info_s_type *ph_sub_ptr = cmph_get_sub_ptr(sub_asub_id);

  if(ph_sub_ptr == NULL)
  {
    return;
  }

  cm_prst_mode_pref = CMPH_PRST_SS_MODE_PREF(sub_asub_id, ph_ptr);
  cm_mode_pref      = CMPH_SS_MODE_PREF(sub_asub_id, ph_ptr);
  CM_MSG_HIGH_2("ADD_LTE : sub: %d, old_mode_pref: %d",sub_asub_id,cm_mode_pref);

  if( cmcall_misc_is_mode_pref(cm_prst_mode_pref, CM_MODE_PREF_TDS_ONLY) &&
      (ph_ptr->device_prop.msim_prop.mode_disabled_in_TSTS  & SYS_SYS_MODE_MASK_TDS))
  {
    cm_mode_pref = cm_add_mode_pref_components(cm_mode_pref,
                   1, SD_SS_MODE_PREF_TDS);
  }
  if( cmcall_misc_is_mode_pref(cm_prst_mode_pref, CM_MODE_PREF_LTE_ONLY) &&
      (ph_ptr->device_prop.msim_prop.mode_disabled_in_TSTS  & SYS_SYS_MODE_MASK_LTE))
  {
    cm_mode_pref = cm_add_mode_pref_components(cm_mode_pref,
                   1, SD_SS_MODE_PREF_LTE );
  }

  if( cm_mode_pref != CMPH_SS_MODE_PREF(sub_asub_id, ph_ptr) )
  {
    cm_pref_s_type *pref_ptr = NULL;
    if ((pref_ptr = cm_pref_ptr()) == NULL) return;

    memscpy(pref_ptr, sizeof(cm_pref_s_type),
            &(ph_sub_ptr->pref_info), sizeof(cm_pref_s_type));
    pref_ptr->mode_pref = cm_mode_pref;

    CM_MSG_HIGH_2(">>PH FORCE_PREF: ADD_LTE : mode_pref : %d sub %d",
                  cm_mode_pref, sub_asub_id);

    (void)cmph_force_pref_on_the_fly_stack(
      cmph_map_sub_stk_to_id(sub_asub_id,MM_STACK_0),
      SD_SS_PREF_REAS_USER,
      CM_ACT_TYPE_PH_OBJ,
      pref_ptr,
      CM_OTASP_ACT_CODE_NONE,
      (cm_act_id_type)ph_ptr,
      CM_ACT_UPDATE_REAS_USER,
      FALSE,
      cmph_get_acq_pri_order_per_sub(sub_asub_id),
      CM_DEFAULT_VALUE);
    cm_mem_free (pref_ptr);
  }
  else
  {
    CM_MSG_HIGH_2("subs %d does not have either TDS or LTE to add in its prst mode_pref(%d)", sub_asub_id, cm_mode_pref);
  }


}


/*===========================================================================

FUNCTION cmph_remove_mode_in_TSTS

DESCRIPTION
  To remove the modes as dictated by NV-mode_disabled_in_TSTS from the mode_pref of
  multimode sub.

DEPENDENCIES
  Ph object must have already been initialized with
  cmph_init().
  standby pref should change from single/dual standby to triple standby

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
void cmph_remove_mode_in_TSTS(
  uint8                   size,
  /* size of array */

  prot_subsc_chg_e_type  *sub_chg
  /* sub_chg array */
)
{
  cmph_s_type *ph_ptr = cmph_ptr();
  cm_mode_pref_e_type cm_mode_pref = CM_MODE_PREF_NONE;

  cmmsimc_state_s_type     *cmmsimc_state = cmmsimc_state_ptr();
  sys_modem_as_id_e_type   sub_asub_id = SYS_MODEM_AS_ID_NONE;

  sub_asub_id = cmph_get_first_sub_with_lte_cap();

  if (!IS_VALID_PH_SUB_PTR(sub_asub_id))
  {
    return;
  }

  cm_mode_pref = cmph_get_ss_mode_pref(sub_asub_id);

  if( cmcall_misc_is_mode_pref(cm_mode_pref, CM_MODE_PREF_TDS_ONLY) &&
      (ph_ptr->device_prop.msim_prop.mode_disabled_in_TSTS  & SYS_SYS_MODE_MASK_TDS) )
  {
    cm_mode_pref = cm_remove_mode_pref_components(cm_mode_pref,
                   1, SD_SS_MODE_PREF_TDS);
  }
  if( cmcall_misc_is_mode_pref(cm_mode_pref, CM_MODE_PREF_LTE_ONLY) &&
      (ph_ptr->device_prop.msim_prop.mode_disabled_in_TSTS  & SYS_SYS_MODE_MASK_LTE) )
  {
    cm_mode_pref = cm_remove_mode_pref_components(cm_mode_pref,
                   1, SD_SS_MODE_PREF_LTE);
  }

  if(cm_mode_pref != cmph_get_ss_mode_pref(sub_asub_id))
  {
    if (sub_asub_id < size && cmutil_is_as_id_valid(sub_asub_id ))
    {
      cm_orig_q_s_type *top_ptr = cmtask_orig_para_get_top( cmph_map_sub_stk_to_id(sub_asub_id,MM_STACK_0) );

      sub_chg[sub_asub_id] |= PROT_SUBSC_CHG_3GPP;
      ph_ptr->sub_info[sub_asub_id]->pref_info.mode_pref = cm_mode_pref;
      if ( top_ptr != NULL )
      {
        top_ptr->orig->orig_mode_pref = cm_mode_pref;
      }
    }

    CM_MSG_HIGH_2("Remove_LTE : sub_with_mm: %d cm_mode_pref : %d ", sub_asub_id, cm_mode_pref);
    if(((ph_ptr->device_prop.msim_prop.user_standby_pref != SYS_MODEM_DS_PREF_AUTO
         && ph_ptr->device_prop.msim_prop.user_standby_pref != SYS_MODEM_DS_PREF_AUTO_NO_TUNEAWAY)
        || ph_ptr->device_prop.msim_prop.is_standby_pref_buffered
        || cmmsimc_state->dev_info.device_mode != cmpmprx_get_device_mode())
        && size >= 3)
    {
      CM_MSG_HIGH_3("Remove_LTE: forcefully mark subsc change %d %d %d",
                    sub_chg[0],sub_chg[1],sub_chg[2]);
      cmmsimc_send_subsc_chgd_current_pref(size, sub_chg);
    }
  }


}

/*===========================================================================

FUNCTION cmph_remove_orig_mode_with_priority_end_per_subs

DESCRIPTION
  Remove the priority queue with activity priority = priority END from the sub.

DEPENDENCIES
  none

RETURN VALUE
 None.

SIDE EFFECTS
  none

===========================================================================*/
void    cmph_remove_orig_mode_with_priority_end_per_subs(
  sys_modem_as_id_e_type         asubs_id
)
{
  if( cmutil_is_as_id_valid(asubs_id) )
  {
    mm_sub_stk_id_s_type local_mm_id;

    local_mm_id.asubs_id = asubs_id;

    CM_MSG_HIGH_1("Remove orig mode with subs priority_end, sub=%d",
                  asubs_id);

    for( local_mm_id.stk_id = MM_STACK_0;
         local_mm_id.stk_id < cmtask_get_num_stacks(asubs_id);
         local_mm_id.stk_id++)
    {
      cmph_remove_orig_mode_with_priority_end(local_mm_id);
    }
  }
}
