/*===========================================================================

FUNCTION  cmph_is_voice_domain_pref_change_allowed

DESCRIPTION
 The function returns ss on which CM need to check that if there is any call
 ongoing or not

DEPENDENCIES
 none

RETURN VALUE
  TRUE if vocie doomain pre fchange is allowed.
  FLASE if vocie doomain pre fchange is not allowed.

SIDE EFFECTS
  none

===========================================================================*/
static boolean cmph_is_voice_domain_pref_change_allowed(
  sys_modem_as_id_e_type  asubs_id
)
{
  return ((cmcall_is_there_a_call_type_per_sub( asubs_id,
           CM_CALL_TYPE_VOICE, NULL ) == CM_CALL_ID_INVALID)
          &&
          (cmcall_is_there_a_call_type_per_device( CM_CALL_TYPE_EMERGENCY) == CM_CALL_ID_INVALID)
          &&
          (cmcall_is_there_a_call_type_per_sub( asubs_id,
              CM_CALL_TYPE_CS_DATA, NULL) == CM_CALL_ID_INVALID)
          &&
          (cmcall_is_there_a_call_type_per_sub( asubs_id,
              CM_CALL_TYPE_SMS, NULL) == CM_CALL_ID_INVALID)
         );
}

