/*===========================================================================

FUNCTION cmph_check_and_reduce_trm_priority

DESCRIPTION
    Check whether CM should LOWER the TRM or not based on ip_call_end_rsp_pend

DEPENDENCIES

RETURN VALUE
  True or FALSE

SIDE EFFECTS
  none

===========================================================================*/

void cmph_check_and_reduce_trm_priority(sys_modem_as_id_e_type asubs_id)
{

    cmph_sub_info_s_type *ph_sub_ptr = cmph_get_sub_ptr(asubs_id);
	if(ph_sub_ptr == NULL)
	{
	  return;
	}
   if((ph_sub_ptr->ip_call_end_rsp_pend == TRUE) && 
   	(cmclnup_get_current_stage() != CM_CLNUP_STAGE_IMS_DEREG) &&
   	((cmclnup_ptr()->clnup_payload.subs_id_bitmask & BM(asubs_id)) ==0))
     {

     	cmph_send_trm_priority_req_proc_type(SYS_PROC_TYPE_NONE,
						asubs_id,
						MM_STACK_0,
						TRUE);
       return;
     }
}


/*===========================================================================

FUNCTION cmph_send_trm_priority_req_proc_type

DESCRIPTION
  Send TRM priority request (based on proc_type) to LTE RCC for multisim configuration
  (DSDS/DSDA)

DEPENDENCIES

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
void cmph_send_trm_priority_req_proc_type(
  sys_proc_type_e_type    proc_type,
  sys_modem_as_id_e_type  as_id,
  multimode_stack_e_type  stk,
  boolean                 client_is_cm
)
{
  #ifdef FEATURE_CM_LTE
  lte_dsds_trm_priority_req_s trm_priority_req;
  cmph_sub_info_s_type *ph_sub_ptr = cmph_get_sub_ptr(as_id);
  reg_cmd_type           *reg_ptr;
  cmph_s_type*          ph_ptr = cmph_ptr();
  
  if (!cmutil_is_as_id_valid(as_id) || ph_sub_ptr == NULL) return;

  /* Allow tuneaway if NV CMEFS_ENABLE_VOLTE_ON_STACK2 is enabled
  ** and there is volte call on stack 2
  */
  if(cmph_get_enable_volte_stack2(as_id) && stk == MM_STACK_2)
  {
    CM_MSG_HIGH_2("SVD: volte_stack2 defined, sub %d not change proc_type to %d",as_id, proc_type);
    return;
  }

  if((client_is_cm == TRUE &&
     proc_type == ph_sub_ptr->ip_pref.proc_type_req_sent_by_cm) || !cmph_is_lte_capable_on_sub(as_id))
  {
    CM_MSG_HIGH_3("LTE_PROC_TYPE: ignore sending new proc_type req %d, sub %d, client_is_cm %d",
                  proc_type, as_id, client_is_cm);
    return;
  }
  if(proc_type == SYS_PROC_TYPE_NONE && client_is_cm)
  {
     ph_sub_ptr->ip_call_end_rsp_pend = FALSE;
  }
  trm_priority_req.proc_type = proc_type;
  if(client_is_cm == TRUE)
  {
    trm_priority_req.client_id = LTE_TRM_PRIORITY_REQ_FROM_CM ;
  }
  else
  {
    trm_priority_req.client_id = LTE_TRM_PRIORITY_REQ_FROM_IMS ;
  }

  CM_MSG_HIGH_3_EXT("CM->LTE: LTE_PROC_TYPE: sub %d, sent new proc_type req %d, client_is_cm %d",
                     as_id, proc_type, client_is_cm, (as_id+1));

  (void) cm_msgr_send( LTE_RRC_DSDS_TRM_PRIORITY_REQ, MSGR_CM_TRM_PRIORITY_REQ,
                       (msgr_hdr_s *)&trm_priority_req, sizeof(lte_dsds_trm_priority_req_s),
                       as_id);

  if(client_is_cm == TRUE)
  {
    ph_sub_ptr->ip_pref.proc_type_req_sent_by_cm = proc_type;
  }
  else
  {
    sys_sys_mode_e_type sys_mode = cmss_get_info_sys_mode(as_id, stk);
    
    CM_MSG_HIGH_2("PROC_TYPE: sys_mode:%d, sent to NAS:%d ",
                 sys_mode,ph_sub_ptr->ip_pref.ims_proc_type_sent_to_nas);

    if(proc_type == SYS_PROC_TYPE_IMS_REGISTRATION
        && (sys_mode == SYS_SYS_MODE_GSM
            || sys_mode == SYS_SYS_MODE_WCDMA
            ||sys_mode == SYS_SYS_MODE_TDS)
       )
    {
      ph_sub_ptr->ip_pref.ims_proc_type_sent_to_nas = TRUE;
    }
    else if(ph_sub_ptr->ip_pref.ims_proc_type_sent_to_nas &&
         proc_type != SYS_PROC_TYPE_IMS_REGISTRATION)
    {
      /* For now NAS needs to handle only IMS REG, so resetting for other proc_type*/
      proc_type = SYS_PROC_TYPE_NONE;
      ph_sub_ptr->ip_pref.ims_proc_type_sent_to_nas = FALSE;
    }
    else
    {
      /* do not send to NAS*/
      return;
    }

    
    reg_ptr = cm_reg_get_buf_else_err_fatal( CM_DATA_PRIORITY_IND );
    
      /* Fill in parameters */
    reg_ptr->cmd.cm_data_prio_ind.as_id = as_id;
    reg_ptr->cmd.cm_data_prio_ind.proc_type = proc_type;
    
    CM_MSG_HIGH_2("CM->NAS: Sending CM_DATA_PRIORITY_IND as_id=%d, proc_type=%d",
                    reg_ptr->cmd.cm_data_prio_ind.as_id,
                    reg_ptr->cmd.cm_data_prio_ind.proc_type);
    
      /* Send the request to NAS */
    cm_reg_send_cmd( reg_ptr );
  }
  #endif
}

