/*===========================================================================

FUNCTION cmph_send_plmn_list_to_lrc

DESCRIPTION
  Informs LTE RRC on which plmns to avoid.
  (DSDS/DSDA)

DEPENDENCIES

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
void cmph_send_plmn_list_to_lrrc(
    sys_modem_as_id_e_type             asubs_id
)
{
  cm_plmn_list_to_avoid_s_type *plmn_avoid;
  errno_enum_type msgr_error = E_SUCCESS;
  sys_aplmn_list_s_type   avoid_plmn_list;
  cmph_sub_info_s_type   *ph_sub_config_ptr = cmph_get_sub_ptr(asubs_id);
  
  if(NULL == ph_sub_config_ptr)
  {
    CM_MSG_HIGH_0("ph_sub_config_ptr is NULL!");
	return;
  }
  plmn_avoid = (cm_plmn_list_to_avoid_s_type*)cm_mem_malloc(
	            sizeof(cm_plmn_list_to_avoid_s_type));
  if(NULL == plmn_avoid)
  {
     sys_err_fatal_null_ptr_exception();
     return;
  }

  avoid_plmn_list = ph_sub_config_ptr->avoid_plmn_list_info;
  plmn_avoid->as_id  = asubs_id;
  plmn_avoid->num_of_plmns_to_avoid = avoid_plmn_list.num_of_plmns_to_avoid;
  memscpy(plmn_avoid->list_to_avoid,sizeof(sys_plmn_id_s_type)*SYS_AVOID_PLMN_LIST_MAX_LENGTH,
	      avoid_plmn_list.plmn,sizeof(sys_plmn_id_s_type)*SYS_AVOID_PLMN_LIST_MAX_LENGTH);
  
  /*use message router to send the avoid plmn list to LRRC.*/
  msgr_error = cm_msgr_send( MM_CM_PLMN_AVOID_LIST_IND, MSGR_MM_CM,
            (msgr_hdr_s*)plmn_avoid, sizeof(cm_plmn_list_to_avoid_s_type),
			asubs_id);

  CM_MSG_HIGH_2("CM->MSGR: sub %d, cmph_send_plmn_list_to_lrrc(), msgr_error=%d", 
                    plmn_avoid->as_id, msgr_error );

  cm_mem_free(plmn_avoid);
  return;
}

