/*===========================================================================

FUNCTION cmph_add_avoid_plmn_to_list

DESCRIPTION


DEPENDENCIES

RETURN VALUE
  TRUE if plmn added
  FALSE if plmn is not added

SIDE EFFECTS
  none

===========================================================================*/
boolean cmph_add_avoid_plmn_to_list(
     sys_modem_as_id_e_type asubs_id,
     sys_plmn_id_s_type  plmn_to_avoid
)
{
  cmph_sub_info_s_type   *ph_sub_config_ptr = cmph_get_sub_ptr(asubs_id);
  sys_aplmn_list_s_type   avoid_plmn_list;
  uint8                   idx=0;

  if(!ph_sub_config_ptr)
  {
    CM_MSG_HIGH_0("ph_sub_config_ptr is NULL.");
    return FALSE;
  }

  avoid_plmn_list = ph_sub_config_ptr->avoid_plmn_list_info;

  /*Resolve duplicates*/
  for(;idx<SYS_AVOID_PLMN_LIST_MAX_LENGTH;idx++)
  {
	  if((plmn_to_avoid.identity[0]==avoid_plmn_list.plmn[idx].identity[0])
		  && (plmn_to_avoid.identity[1]==avoid_plmn_list.plmn[idx].identity[1])
		  && (plmn_to_avoid.identity[2]==avoid_plmn_list.plmn[idx].identity[2]))
	  {
	    CM_MSG_HIGH_0("Plmn already present in avoid plmn list. Skip");
      return FALSE;
	  }
  }
  CM_MSG_HIGH_3("adding plmn %d %d %d to avoid",plmn_to_avoid.identity[0],plmn_to_avoid.identity[1], plmn_to_avoid.identity[2]);
  if(SYS_AVOID_PLMN_LIST_MAX_LENGTH != ph_sub_config_ptr->avoid_plmn_list_info.num_of_plmns_to_avoid)
  {
    ph_sub_config_ptr->avoid_plmn_list_info.num_of_plmns_to_avoid++;
  }
  sys_add_avoid_plmn_to_list(&(ph_sub_config_ptr->avoid_plmn_list_info),&plmn_to_avoid);
  return TRUE;
}
