/*===========================================================================

FUNCTION cmph_set_ssac_hyst_timer_req

DESCRIPTION
  UPdates value of t_ssac in CMPH context for volte hysteresis
  updates the NV as well
  If there is soem timer running currently it will continue to
  run with old value itself.

DEPENDENCIES

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
void cmph_set_ssac_hyst_timer_req(
  cm_mm_set_ssac_hyst_req_s_type set_ssac_hyst_timer_req,
  sys_modem_as_id_e_type asubs_id
)
{
  uint16 write_size;
  cm_ssac_hvolte_s_type ssac_hvolte_control;
  uint16 t_ssac_val = set_ssac_hyst_timer_req.t_ssac_val;
  volte_sub_info_s_type *volte_sub_info_ptr = cmph_get_volte_sub_info_ptr(asubs_id);

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* if t_ssac_val is not set to anything between 0 and 512
     QMI itself would reject the command so CM does not expect this input at all
  */
  if(t_ssac_val > 512)
  {
    CM_ASSERT(0);
    return;
  }

  memset(&ssac_hvolte_control, 0, sizeof(ssac_hvolte_control));
  /* fill the structure to be written in EFS from current volte pointer */
  {
    ssac_hvolte_control.is_hvolte = volte_sub_info_ptr->is_hvolte;
    ssac_hvolte_control.is_ssac_hvolte = volte_sub_info_ptr->is_ssac_hvolte;
    ssac_hvolte_control.volte_ssac_sr_control = volte_sub_info_ptr->volte_ssac_sr_control;
    ssac_hvolte_control.volte_acb_sr_control = volte_sub_info_ptr->volte_acb_sr_control;
    ssac_hvolte_control.t_ssac = t_ssac_val;
  }

  write_size = sizeof(cm_ssac_hvolte_s_type);

  /* do not create the file if it was not already existing */
  if (!cmefs_fs_write_no_create(CMEFS_SSAC_HVOLTE,
                                (byte *)&ssac_hvolte_control,
                                write_size,
                                asubs_id))
  {
    CM_ERR_1("t_ssac: mcfg_fs_write for ssac_hvolte_control fail sub %d",asubs_id);
  }
  else
  {
    CM_MSG_HIGH_2("t_ssac: volte hysteresis timer updated with value %d, sub %d",
                  t_ssac_val, asubs_id);
    volte_sub_info_ptr->t_ssac = t_ssac_val;
  }
  return;
}

/*===========================================================================

FUNCTION cmph_send_get_ssac_hyst_timer_rsp

DESCRIPTION
  Sends the current value of the t_ssac hysteresis timer value to
  CM clients via MSGR interface MM_CM_GET_SSAC_HYST_TIMER_RSP.

DEPENDENCIES

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
void cmph_send_get_ssac_hyst_timer_rsp( sys_modem_as_id_e_type asubs_id )
{
  cm_mm_get_ssac_hyst_timer_rsp_s_type *ssac_hyst_timer_rsp;
  volte_sub_info_s_type *volte_sub_info_ptr = cmph_get_volte_sub_info_ptr(asubs_id);

  ssac_hyst_timer_rsp = (cm_mm_get_ssac_hyst_timer_rsp_s_type *)cm_mem_malloc(
                          sizeof(cm_mm_get_ssac_hyst_timer_rsp_s_type));

  if(ssac_hyst_timer_rsp == NULL)
  {
    CM_ERR_0("Heap exhausted, cm_mem_malloc() returned NULL");
    return;
  }
  ssac_hyst_timer_rsp->t_ssac_val = volte_sub_info_ptr->t_ssac;

  (void) cm_msgr_send( MM_CM_GET_SSAC_HYST_TIMER_RSP, MSGR_MM_CM,
                       (msgr_hdr_s *)ssac_hyst_timer_rsp, sizeof(cm_mm_get_ssac_hyst_timer_rsp_s_type),
                       asubs_id);
  CM_MSG_HIGH_2("CM->MSGR: t_ssac: send SSAC_HYST_TIMER_RSP with value as %d, sub %d",
                volte_sub_info_ptr->t_ssac,
                asubs_id);
  cm_mem_free(ssac_hyst_timer_rsp);
}

/*===========================================================================
FUNCTION cmph_load_prst_dual_standby_pref

DESCRIPTION
  updates the ph_ptr with persistent standby values from NV


DEPENDENCIES
  Phone object must have already been initialized with
  cmph_init().

RETURN VALUE
  None

SIDE EFFECTS
  None

===========================================================================*/
static void cmph_load_prst_dual_standby_pref ( void )

{

#ifdef FEATURE_MMODE_DUAL_SIM
  cmph_s_type *ph_ptr = cmph_ptr();

  if(ph_ptr->device_prop.msim_prop.default_data_subs != ph_ptr->device_prop.msim_prop.prst_dual_standby_pref.default_data_subs)
  {
    ph_ptr->device_prop.msim_prop.default_data_subs = ph_ptr->device_prop.msim_prop.prst_dual_standby_pref.default_data_subs;
    ph_ptr->device_prop.msim_prop.dds_switch_type = DDS_CAUSE_PERMANENT;
    ph_ptr->device_prop.msim_prop.new_default_data_subs = ph_ptr->device_prop.msim_prop.prst_dual_standby_pref.default_data_subs;

    cmpmprx_msim_subsc_changed(ph_ptr->device_prop.msim_prop.active_subs,
                               ph_ptr->device_prop.msim_prop.default_data_subs,
                               ph_ptr->device_prop.msim_prop.dds_switch_type);

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
    /* Send the PH Event that Standby Preferences have changed */
    cmph_event( CM_PH_EVENT_DUAL_STANDBY_PREF );

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  }
#endif
}

/*===========================================================================

FUNCTION cmph_check_and_send_standby_pref_change

DESCRIPTION
  If standby pref got buffered due to voice call,
  update pref change now.

DEPENDENCIES

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
void cmph_check_and_send_standby_pref_change( void )
{
  cmph_s_type *ph_ptr = cmph_ptr();

  if(ph_ptr->device_prop.msim_prop.is_standby_pref_buffered &&
      (ph_ptr->device_prop.msim_prop.user_standby_pref == SYS_MODEM_DS_PREF_AUTO ||
       ph_ptr->device_prop.msim_prop.user_standby_pref == SYS_MODEM_DS_PREF_AUTO_NO_TUNEAWAY) &&
      cmpmprx_is_ok_to_enforce_device_policy(CM_CALL_ID_INVALID)
    )
  {
    cm_ph_cmd_dual_standby_pref( NULL,
                                 NULL,
                                 CM_CLIENT_ID_ANONYMOUS,
                                 ph_ptr->device_prop.msim_prop.user_standby_pref,
                                 SYS_MODEM_AS_ID_NO_CHANGE,
                                 SYS_MODEM_AS_ID_NO_CHANGE,
                                 SYS_MODEM_AS_ID_NO_CHANGE,
                                 SYS_MODEM_AS_ID_NO_CHANGE,
                                 ph_ptr->device_prop.msim_prop.dds_switch_type,
                                 FALSE);
  }
}

