/*===========================================================================

FUNCTION cmph_get_sub_in_emg_cb

DESCRIPTION
  Get the sub which is in emergency cb mode.

DEPENDENCIES
  None.

RETURN VALUE
  sys_modem_as_id_e_type.

SIDE EFFECTS
  None.

===========================================================================*/
sys_modem_as_id_e_type  cmph_get_sub_in_emg_cb(void)
{
  sys_modem_as_id_e_type sub;
  cmph_sub_info_s_type *ph_sub_ptr = NULL;

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  if(!cmph_is_in_emergency_cb())
  {
    return SYS_MODEM_AS_ID_NONE;
  }

  if (!cmph_is_msim())
  {
    return SYS_MODEM_AS_ID_1;
  }

  for( sub = SYS_MODEM_AS_ID_1; cmutil_is_as_id_valid(sub); sub ++ )
  {
    ph_sub_ptr = cmph_get_sub_ptr(sub);

    if( ph_sub_ptr != NULL &&
        (ph_sub_ptr->emerg_call_prop.ph_state == CM_PH_STATE_EMERG_CB ||
         ph_sub_ptr->emerg_call_prop.ecbm_rat == SYS_SYS_MODE_WLAN))
    {
      return sub;
    }
  }

  CM_ERR_0("No Sub found in emerg_cb");
  return SYS_MODEM_AS_ID_1;
}

