/*===========================================================================

FUNCTION cmph2_check_device_init_status

DESCRIPTION
  This function checks the current RF/GPS init status and returns the proper 
  error value.

RETURN VALUE
  cm_ph_cmd_err_e_type 

===========================================================================*/
cm_ph_cmd_err_e_type cmph2_check_device_init_status(void)
{
  oprt_mode_data_s_type *ph_oprt_data_ptr = &cmph_ptr()->device_prop.ph_oprt_mode;

  if (!ph_oprt_data_ptr->is_gps_pgi_init_complete && 
     ph_oprt_data_ptr->rf_init_info.status == CM_RF_INIT_READY
  )
  {
    return CM_PH_CMD_ERR_GPS;
  }    
  else if (ph_oprt_data_ptr->rf_init_info.status == CM_RF_INIT_FAILED &&
         ph_oprt_data_ptr->rf_init_info.error_code == CM_RF_FAILURE_HW)
  {
    return CM_PH_CMD_ERR_RF_HW;
  }
  else
  {
    return CM_PH_CMD_ERR_RF_SW;
  }
}

/*===========================================================================

FUNCTION cmph2_proc_device_init_status

DESCRIPTION
  Process RF/gps initialization status update.

  If oprt mode change is to be done, no need to send ph event to QMI DMS as 
  as part of oprt mode change process, CM_PH_EVENT_OPRT_MODE will be sent.
  Else trigger a ph event to update cm clients with the latest rf/gps init status. 
  The status can be used for AP to not trigger oprt mode change is modem is not
  ready in terms of rf or gps initialization.

  Note: RF init status (succss/failiure) and GPS init complettion should have 
  updated prior to this function.

RETURN VALUE
  None 

===========================================================================*/
void cmph2_proc_device_init_status(  
  const rf_init_comp_msg_type  *rfm_ind,
  boolean                       oprt_mode_chg
)
{
  oprt_mode_data_s_type *ph_oprt_data_ptr = &cmph_ptr()->device_prop.ph_oprt_mode;

  if (rfm_ind)
  {
    if (rfm_ind->rf_init_success)
    {
      ph_oprt_data_ptr->rf_init_info.error_code = CM_RF_FAILURE_NONE;
    }
    else if (rfm_ind->failure_type == RF_INIT_FAILURE_HW)
    {
      ph_oprt_data_ptr->rf_init_info.error_code = CM_RF_FAILURE_HW;
    }
    else
    {
      ph_oprt_data_ptr->rf_init_info.error_code = CM_RF_FAILURE_SW;
    }
    CM_MSG_HIGH_4("RF->CM: INIT_STATUS: rf staus %d, fail_type %d, gps %d, oprt_mode_chg %d",
                     ph_oprt_data_ptr->rf_init_info.status,
                     ph_oprt_data_ptr->rf_init_info.error_code,
                     ph_oprt_data_ptr->is_gps_pgi_init_complete,
                     oprt_mode_chg);
  }
  else
  {
    CM_MSG_HIGH_4("GPS->CM: INIT_STATUS: rf staus %d, fail_type %d, gps %d, oprt_mode_chg %d",
                     ph_oprt_data_ptr->rf_init_info.status,
                     ph_oprt_data_ptr->rf_init_info.error_code,
                     ph_oprt_data_ptr->is_gps_pgi_init_complete,
                     oprt_mode_chg);
  }

  /* Send ph event to update rf_init_status and gps_init_status to clients */
  if (!oprt_mode_chg)
  {
    cmph_event(CM_PH_EVENT_OPRT_MODE);
  }
}

/*===========================================================================

FUNCTION cmph2_update_device_init_status

DESCRIPTION
  Update rf/gps init status to cm clients.

RETURN VALUE
  None 

===========================================================================*/
void cmph2_update_device_init_status(  
  cm_ph_info_s_type  *ph_info_ptr
)
{
  ph_info_ptr->is_gps_init_completed 
    = cmph_ptr()->device_prop.ph_oprt_mode.is_gps_pgi_init_complete;
  ph_info_ptr->rf_init_status
    = cmph_ptr()->device_prop.ph_oprt_mode.rf_init_info;
}


/*===========================================================================

FUNCTION cmph_get_ss_lte_band_pref

DESCRIPTION
return the LTE band mask on the sub.

DEPENDENCIES
None

RETURN VALUE
None

SIDE EFFECTS
none

===========================================================================*/
sys_lte_band_mask_e_type cmph_get_ss_lte_band_pref(

  sys_modem_as_id_e_type asubs_id,

  cmph_s_type            *ph_ptr
)
{
  sys_lte_band_mask_e_type lte_band = SYS_LTE_BAND_MASK_CONST_NONE;

  if(!(asubs_id >= SYS_MODEM_AS_ID_1 &&
       asubs_id < ARR_SIZE(ph_ptr->sub_info) &&
       asubs_id < SYS_MODEM_AS_ID_NO_CHANGE))
  {
    asubs_id = SYS_MODEM_AS_ID_1;
  }
  if(ph_ptr->sub_info[asubs_id] != NULL)
  {
    lte_band = ph_ptr->sub_info[asubs_id]->pref_info.lte_band_pref;
  }

  return lte_band;
}

/*===========================================================================

FUNCTION cmph_send_high_prio_activity_ind

DESCRIPTION
  Sends an indication to REG to detach locally, when a high priority activity is triggered
  while CM is waiting for PS_DETACH_CNF from NAS

DEPENDENCIES

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
void cmph_send_high_prio_activity_ind (

  /* detach required or not */
  boolean         local_detach
)
{

#ifdef CM_GW_SUPPORTED

  reg_cmd_type                          *reg_ptr;
  uint8                                  i;
  uint8 sub_idx;
  cmregprx_stack_info_s_type *regprx_stk_ptr;

  for (sub_idx = 0; sub_idx < cmregprx_get_info_ptr()->sub_cnt && sub_idx < MAX_SIMS; sub_idx ++)
  {
    for(i = 0; i < cmregprx_get_info_ptr()->sub_info[sub_idx]->stk_cnt; i++)
    {
      multimode_stack_e_type stk = cmregprx_map_to_mm_stk(i);
      mm_sub_stk_id_s_type mm_id = cmph_map_sub_stk_to_id(sub_idx,stk);
      regprx_stk_ptr = cmregprx_get_stk_ptr(mm_id);
      if(regprx_stk_ptr != NULL &&
          cmutil_is_mm_id_valid(mm_id) && mm_id.stk_id != MM_STACK_ALL &&
          cmregprx_get_substate(mm_id) == CMREGPRX_SUBSTATE_WAIT_PS_DETACH_CNF )
      {
        /* Get reg cmd. buffer and populate params */
        reg_ptr =  cm_reg_get_buf_else_err_fatal( CM_HIGH_PRIORITY_ACTIVITY_IND );
        reg_ptr->cmd.cm_high_priority_activity_ind.local_detach = local_detach;
        reg_ptr->cmd.cm_high_priority_activity_ind.as_id = sub_idx;
        reg_ptr->cmd.cm_high_priority_activity_ind.stack_id = regprx_stk_ptr->nas_stack_id;

        CM_MSG_HIGH_2_ASID("CM->NAS: High Priority Activity Ind to REG: %d", sub_idx, local_detach );

        /* Send PS_DEATCH_COMPLETE_IND to Reg */
        cm_reg_send_cmd( reg_ptr );

        cm_high_prio_activity_ind_sent = local_detach;
      }
    }
  }

#endif
}

/*===========================================================================

FUNCTION cmph_get_ph_sub_avail_mask

DESCRIPTION
  Get the sub avail mask for the specified sub.

DEPENDENCIES
  None

RETURN VALUE
  uint8

SIDE EFFECTS
  None

===========================================================================*/
uint8  cmph_get_ph_sub_avail_mask (
  uint8  index
)
{
  cmph_s_type *ph_ptr = cmph_ptr();
  uint8  sub_avail_mask = 0;

  if (IS_VALID_PH_SUB_PTR(index))
  {
    if (ph_ptr->sub_info[index]->is_3gpp_subs_avail)
    {
      sub_avail_mask |= MASK_GPP;
    }
    if (ph_ptr->sub_info[index]->is_3gpp2_subs_avail)
    {
      sub_avail_mask |= MASK_GPP2;
    }
  }
  return sub_avail_mask;
}

