/*===========================================================================

FUNCTION  cmph_determine_stk_per_rat

DESCRIPTION
 The function determines cm_ss base on asubs_id and rat.

DEPENDENCIES
 none

RETURN VALUE
  multimode_stack_e_type.

SIDE EFFECTS
  none

===========================================================================*/
multimode_stack_e_type  cmph_determine_stk_per_rat (
  sys_modem_as_id_e_type  asubs_id,
  sys_sys_mode_e_type     rat
)
{
  /* decide stack base on rat
  */
  if(rat == SYS_SYS_MODE_HDR)
  {
    if(cmss_is_stack1_operational(asubs_id))
    {
      return MM_STACK_1;
    }
    else
    {
      return MM_STACK_0;
    }
  }

  if (cmmsc_get_1x_sub() == asubs_id &&
      cmss_is_stack2_operational(asubs_id) &&
      rat == SYS_SYS_MODE_LTE)
  {
    return MM_STACK_2;
  }
  else
  {
    return MM_STACK_0;
  }
}


