/*===========================================================================

FUNCTION cmph_enter_emergency_cb_wlan

DESCRIPTION

  Enter emergency callback mode for WLAN  and notify clients

DEPENDENCIES
  Phone object must have already been initialized with
  cmph_init().

RETURN VALUE
  None.

SIDE EFFECTS
  None.

===========================================================================*/
void cmph_enter_emergency_cb_wlan(
  sys_modem_as_id_e_type  subs_id
)
{
  cmph_s_type   *ph_ptr = cmph_ptr();

  /* Store the RAT on which CM enters callback mode
  */
  if (IS_VALID_PH_SUB_PTR(subs_id))
  {
    ph_ptr->sub_info[subs_id]->emerg_call_prop.ecbm_rat = SYS_SYS_MODE_WLAN;
    ph_ptr->sub_info[subs_id]->emerg_call_prop.ph_state = CM_PH_STATE_EMERG_CB;
    ph_ptr->sub_info[subs_id]->emerg_call_prop.ecbm_exit_reason = CM_ECBM_EXIT_REASON_NORMAL;
  }
  cmph_event( CM_PH_EVENT_SYS_SEL_PREF );
  cmlog_enter_emergency_cb(subs_id);
}


/*===========================================================================

FUNCTION cmph_set_t_wwan_911_req

DESCRIPTION
  UPdates value of t wwan 911 timer.
  New values will apply for the calls originated after setting the timer.

DEPENDENCIES

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
void cmph_set_t_wwan_911_req(
  uint16 t_wwan_911_val,
  sys_modem_as_id_e_type asubs_id
)
{

  uint16 write_size;
  mcfg_fs_status_e_type status;
  cmph_custom_emerg_call_info_s_type  e911_info;
  cmph_sub_info_s_type       *ph_sub_config_ptr = cmph_get_sub_ptr(asubs_id);

  if(ph_sub_config_ptr == NULL)
  {
    CM_MSG_HIGH_1("cmph sub config pointer[%d] is NULL",asubs_id);
    return;
  }

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* if t_ssac_val is not set to anything between 0 and 1024
  QMI itself would reject the command so CM does not expect this input at all */

  if(t_wwan_911_val > 1024)
  {
    t_wwan_911_val = 40;
  }
  memset(&e911_info, 0, sizeof(cmph_custom_emerg_call_info_s_type));
  /* fill the structure to be written in EFS from current volte pointer */
  {
    e911_info.is_ecbm_required = ph_sub_config_ptr->emerg_call_prop.is_ecbm_required;
    e911_info.is_alternate_redial_algorithm = ph_sub_config_ptr->emerg_call_prop.is_alternate_redial_algorithm;
    e911_info.hold_concurrent_voicecall_during_emergency = ph_sub_config_ptr->emerg_call_prop.hold_concurrent_voicecall_during_emergency;
    e911_info.is_wlan_e911_call_supp = ph_sub_config_ptr->emerg_call_prop.is_wlan_e911_call_supp;
    e911_info.twwan_timer = t_wwan_911_val;
  }
  write_size = sizeof(cmph_custom_emerg_call_info_s_type);
  /* do not create the file if it was not already existing */
  status = cmefs_fs_write( CMEFS_CUSTOM_EMERG_INFO,
                           (byte *)&e911_info,
                           (int)write_size,
                           asubs_id);

  if ( status != TRUE )
  {
    CM_ERR_2( "t_wwan_911: write for e911 custom info fail status=%d, errno %d", status, mcfg_fs_errno(MCFG_FS_TYPE_EFS));
  }
  else
  {
    CM_MSG_HIGH_1("t_wwan_911: timer updated with value %d", t_wwan_911_val);
    ph_sub_config_ptr->emerg_call_prop.twwan_timer = t_wwan_911_val;
  }
  return;
}

/*===========================================================================

FUNCTION cmph_send_get_t_wwan_911_rsp

DESCRIPTION
  Sends the current value of the t_wwan_911 timer to clients.

DEPENDENCIES

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
void cmph_send_get_t_wwan_911_rsp( sys_modem_as_id_e_type asubs_id )
{
  cm_mm_get_t_wwan_911_rsp_s_type *t_wwan_911_rsp;
  cmph_sub_info_s_type *ph_sub_ptr = cmph_get_sub_ptr(asubs_id);

  if(ph_sub_ptr == NULL)
  {
    return;
  }

  t_wwan_911_rsp = (cm_mm_get_t_wwan_911_rsp_s_type *)cm_mem_malloc(
                     sizeof(cm_mm_get_t_wwan_911_rsp_s_type));

  if(t_wwan_911_rsp == NULL)
  {
    CM_ERR_0("Heap exhausted, cm_mem_malloc() returned NULL");
    return;
  }
  t_wwan_911_rsp->t_wwan_911_val = ph_sub_ptr->emerg_call_prop.twwan_timer;

  (void) cm_msgr_send( MM_CM_GET_T_WWAN_911_RSP, MSGR_MM_CM,
                       (msgr_hdr_s *)t_wwan_911_rsp, sizeof(cm_mm_get_t_wwan_911_rsp_s_type),
                       asubs_id);
  CM_MSG_HIGH_2("t_wwan_911: sub %d, send resp with timer value %d",
                asubs_id, t_wwan_911_rsp->t_wwan_911_val);
  cm_mem_free(t_wwan_911_rsp);
  return;
}

/*===========================================================================

FUNCTION cmph_reset_network_pref

DESCRIPTION
  Reset variables related to Get Networks (manual search).

DEPENDENCIES
  None

RETURN VALUE
  None

SIDE EFFECTS
  None

===========================================================================*/
void cmph_reset_network_pref(
    sys_modem_as_id_e_type    asubs_id,
    boolean                   clear_pf_scan_info
)
{
  cmph_sub_info_s_type *ph_net_sub_ptr = cmph_get_net_sub_ptr(asubs_id);
  cmph_s_type          *ph_ptr = cmph_ptr();

  CM_MSG_HIGH_2("GET_NET: Reset manual search info, sub %d clear_pf_scan_info %d", 
                asubs_id, clear_pf_scan_info);

  ph_ptr->device_prop.man_srch_state = CM_MAN_SRCH_STATE_NONE;
  ph_ptr->device_prop.man_srch_timer_uptime = 0;
  ph_ptr->device_prop.man_srch_max_timer_uptime = 0;
  ph_ptr->device_prop.man_srch_retries = 0;
  
  ph_ptr->device_prop.mm_id_for_get_networks.asubs_id = SYS_MODEM_AS_ID_NONE;
  ph_ptr->device_prop.mm_id_for_get_networks.stk_id   = MM_STACK_NONE;

  if(ph_ptr->device_prop.pf_scan_info && clear_pf_scan_info)
  {
    cm_mem_free(ph_ptr->device_prop.pf_scan_info);
    ph_ptr->device_prop.pf_scan_info = NULL;
  }
    
  if(cmutil_is_as_id_valid(asubs_id) && ph_net_sub_ptr != NULL)
  {
    ph_net_sub_ptr->pref_info.network_type          = CM_MODE_PREF_NONE;
    ph_net_sub_ptr->pref_info.network_band_pref     = CM_BAND_PREF_NONE;
    SYS_LTE_BAND_MASK_CLR_ALL_BANDS(&ph_net_sub_ptr->pref_info.network_lte_band_pref);
    ph_net_sub_ptr->pref_info.network_tds_band_pref = CM_BAND_PREF_NONE;
    ph_net_sub_ptr->pref_info.network_list_type     = CM_NETWORK_LIST_NONE;
    ph_net_sub_ptr->pref_info.ignore_manual_bst     = FALSE;
    ph_net_sub_ptr->pref_info.network_list_cnf      = SYS_PLMN_LIST_NONE;
  }

  cmph_resume_ps_on_non_dds();
}

/*===========================================================================

FUNCTION cm_ph_get_is_ecbm_required_status_per_subs

DESCRIPTION
 returns the status of is_ecbm_required per subscription

DEPENDENCIES
  None

RETURN VALUE
  TRUE if ECBM is required
  False otherwise

SIDE EFFECTS
  none

===========================================================================*/
boolean cm_ph_get_is_ecbm_required_status_per_subs(sys_modem_as_id_e_type asubs_id)
{
  boolean                 is_ecbm_required  = FALSE;
  cmph_sub_info_s_type *ph_sub_config_ptr = NULL;

  if( (asubs_id > SYS_MODEM_AS_ID_NONE && asubs_id < SYS_MODEM_AS_ID_MAX) && (asubs_id != SYS_MODEM_AS_ID_NO_CHANGE))
  {
    ph_sub_config_ptr = cmph_get_sub_ptr(asubs_id);
    if(ph_sub_config_ptr == NULL)
    {
      CM_MSG_HIGH_1("cmph sub config pointer[%d] is NULL", asubs_id);
      return FALSE;
    }
    /* Get the is_ecbm_required from the CM PH object */
    is_ecbm_required = ph_sub_config_ptr->emerg_call_prop.is_ecbm_required;
  }
  else
  {
    CM_ERR_1("Unsupported asubs_id %d", asubs_id);
    return FALSE;
  }

  return is_ecbm_required;
}
/*==========================================================================

FUNCTION cmph_read_imsi_hplmn

DESCRIPTION
  Function that reads EF-IMSI and return HPLMN(MCC-MNC)

RETURN VALUE
  boolean  Flag indicating whether EF-IMSI read
           from the SIM successfully (TRUE) or unsuccessfully(FALSE).

DEPENDENCIES
  None
===========================================================================*/
static boolean cmph_read_imsi_hplmn
(
  sys_plmn_id_s_type *imsi_ptr,

  mmgsdi_session_type_enum_type    session_type

)
{
  boolean                       status    = FALSE;
  mmgsdi_app_enum_type          app_type;
  byte                          imsi[MMGSDI_IMSI_LEN] = {0};
  byte                          admin_data[CMMMGSDI_RPM_AD_SIZE] = {0};
  boolean                       plmn_is_undefined_ptr;
  boolean                       mnc_includes_pcs_digit_ptr;
  sys_mcc_type                  mcc=SYS_WILDCARD_MCC;
  sys_mnc_type                  mnc=SYS_WILDCARD_MNC;
  sys_modem_as_id_e_type        asubs_id= SYS_MODEM_AS_ID_1;


  app_type = cm_mmgsdi_ssn_tbl_get_app_type_for_type(
               session_type);

  /* Read EF-IMSI */
  status = cmmmgsdi_read(session_type,
                         (app_type == MMGSDI_APP_SIM ? MMGSDI_GSM_IMSI : MMGSDI_USIM_IMSI),
                         0,
                         MMGSDI_IMSI_LEN,
                         (uint8 *)imsi,
                         sizeof(imsi),
                         transparent);

  /* Read EF-AD to get MNC length */
  if(status)
  {
    status = cmmmgsdi_read(session_type,
                           (app_type == MMGSDI_APP_SIM ? MMGSDI_GSM_AD : MMGSDI_USIM_AD),
                           0,
                           CMMMGSDI_RPM_AD_SIZE,
                           (uint8 *)admin_data,
                           sizeof(admin_data),
                           transparent);
  }

  /* Extract MCC and MNC */
  if(status)
  {
    /*
    ** Fill MCC Digit 1 and MCC Digit 2
    */
    imsi_ptr->identity[0] = (byte)(( ( imsi[1] & 0xF0 ) / 0x10 ) +
                                   ( ( imsi[2] & 0x0F ) * 0x10 ));

    /*
    ** Fill MCC Digit 3 and MNC Digit 3
    */
    imsi_ptr->identity[1] = (byte)(( ( imsi[2] & 0xF0 ) / 0x10 ) +
                                   ( ( imsi[4] & 0x0F ) * 0x10 ));

    /*
    ** If 2 digits MNC is indicated in EF-AD then set MNC digit 3 to 'F'.
    */
    if ((admin_data[3] & 0x0F) == 0x02)
    {
      CM_MSG_MED_0("2 digit MNC");

      imsi_ptr->identity[1] |= 0xF0;
    }

    /*
    ** Fill MNC Digit 1 and MNC Digit 2
    */
    imsi_ptr->identity[2] = imsi[3];

    CM_MSG_HIGH_3_EXT("Read IMSI - HPLMN : 0x%02x, 0x%02x, 0x%02x",
                      imsi_ptr->identity[0],imsi_ptr->identity[1],imsi_ptr->identity[2],
                      (SESSION_TO_AS_ID(session_type)+1));
    /*Store MCC/MNC Values*/
    sys_plmn_get_mcc_mnc2(*imsi_ptr,&plmn_is_undefined_ptr,&mnc_includes_pcs_digit_ptr,
                            &mcc,&mnc);
    if(session_type == MMGSDI_GW_PROV_PRI_SESSION)
    {
      asubs_id = SYS_MODEM_AS_ID_1;
    }
    else if(session_type == MMGSDI_GW_PROV_SEC_SESSION)
    {
      asubs_id = SYS_MODEM_AS_ID_2;
    }

    if(asubs_id < MAX_SIMS && cmph_ptr()->sub_info[asubs_id] != NULL)
    {
      cmph_ptr()->sub_info[asubs_id]->gwl_mcc=mcc;
      cmph_ptr()->sub_info[asubs_id]->gwl_mnc=mnc;
      sd_misc_update_3gpp_imsi(asubs_id,mcc,mnc);
    }
  }

  return status;

} /* cmph_read_imsi_hplmn() */

/*==========================================================================

FUNCTION cmph_read_ehplmn_list

DESCRIPTION
  Function that reads EHPLMN list and 

RETURN VALUE
  boolean  Flag indicating whether EHPLMN read
           from the SIM successfully (TRUE) or unsuccessfully(FALSE).

DEPENDENCIES
  None
===========================================================================*/
boolean cmph_read_ehplmn_list(sys_modem_as_id_e_type asubs_id)
{

  mmgsdi_session_type_enum_type    session_type = AS_ID_TO_GW_SESSION(asubs_id);
  mmgsdi_session_id_type           session_id;
  cm_mmgsdi_error_e_type           status;
  mmgsdi_data_type                 read_data;
  sys_plmn_id_s_type               *ehplmn_list = NULL;
  mmgsdi_len_type                  file_size = 0;
  size_t                           plmnCount = 0;
  size_t                           index, count =0;
  cmph_sub_info_s_type             *ph_sub_config_ptr = cmph_get_sub_ptr(asubs_id);
  boolean                          ret_val = FALSE;


  #ifndef CM_DEBUG
  if( cm_mmgsdi_ssn_tbl_get_app_type_for_type(session_type) != MMGSDI_APP_USIM )
  {
    CM_MSG_HIGH_1("APP not MMGSDI_APP_USIM; session type: %d",
            session_type);

    return FALSE;
  }
  #endif
  
  status = cm_mmgsdi_ssn_tbl_get_id_for_type(session_type, &session_id);

  if (CM_MMGSDI_SUCCESS != status)
  {
    CM_ERR_2("Unable to get session id; session type: %d, err: %d",
            session_type, status);

    return FALSE;
  }

  if (MMGSDI_SUCCESS == mmgsdi_session_read_cache_file_size(session_id, MMGSDI_USIM_EHPLMN, &file_size))
  {

    /*
       ** Set the maximum file size for the EHPLMN List.
       */
    file_size = MIN(file_size, (SYS_EHPLMN_LIST_MAX_LENGTH - 1) * sizeof(sys_plmn_id_s_type));

    if( file_size != 0 )
    {
      ehplmn_list = (sys_plmn_id_s_type *)cm_mem_malloc(file_size);
  
      if( ehplmn_list == NULL )
      {
        CM_ERR_0("mem_alloc failed for ehplmn_list.plmn ");
        return FALSE;
      }
          
      read_data.data_ptr = (uint8 *) ehplmn_list;
      read_data.data_len = (int32) file_size;
  
      // Read the EHPLMN list
      if (MMGSDI_SUCCESS == mmgsdi_session_read_cache(session_id, MMGSDI_USIM_EHPLMN, read_data) )
      {
        plmnCount = (file_size / sizeof(sys_plmn_id_s_type));
      }
    }
  }

  if (plmnCount != 0)
  { 
    for (index = 0; index < plmnCount; index++)
    {
      if (!sys_plmn_id_is_undefined(ehplmn_list[index]) && sys_plmn_id_is_valid(ehplmn_list[index]))
      {
        ehplmn_list[count] = ehplmn_list[index];
        count++;
      }
    }

    plmnCount = count;
  }

  if( plmnCount == 0 &&
      ph_sub_config_ptr != NULL &&
      sys_plmn_id_is_valid(ph_sub_config_ptr->gwl_imsi_plmn) )
  {
    ehplmn_list = (sys_plmn_id_s_type *)cm_mem_malloc(sizeof(sys_plmn_id_s_type));
    memscpy(ehplmn_list, sizeof(sys_plmn_id_s_type),
                &ph_sub_config_ptr->gwl_imsi_plmn, sizeof(sys_plmn_id_s_type));
    plmnCount++;
  }
  
  if (plmnCount != 0)
  { 
    if(ph_sub_config_ptr != NULL)
    {
      ph_sub_config_ptr->ehplmn_list.length = plmnCount;
      ph_sub_config_ptr->ehplmn_list.plmn = 
          (sys_plmn_id_s_type *)cm_mem_malloc(plmnCount * sizeof(sys_plmn_id_s_type));

      if( ph_sub_config_ptr->ehplmn_list.plmn != NULL )
      {
        memscpy(ph_sub_config_ptr->ehplmn_list.plmn, plmnCount * sizeof(sys_plmn_id_s_type),
                ehplmn_list, plmnCount * sizeof(sys_plmn_id_s_type));
      }

      ret_val = TRUE;

      CM_MSG_HIGH_1("cmph_read_ehplmn_list SUCCESS plmn_count=%d", plmnCount);
    }
    
  }

  if( ehplmn_list != NULL )
  {
    cm_mem_free(ehplmn_list);
  }
  
  return ret_val;
}

/*==========================================================================

FUNCTION cmph_clear_ehplmn_list

DESCRIPTION
  Function that reads EHPLMN list and 

RETURN VALUE
  boolean  Flag indicating whether EHPLMN read
           from the SIM successfully (TRUE) or unsuccessfully(FALSE).

DEPENDENCIES
  None
===========================================================================*/
void cmph_clear_ehplmn_list(sys_modem_as_id_e_type asubs_id)
{

  cmph_sub_info_s_type             *ph_sub_config_ptr = cmph_get_sub_ptr(asubs_id);

  if(ph_sub_config_ptr != NULL)
  {
    ph_sub_config_ptr->ehplmn_list.length = 0;
    if( ph_sub_config_ptr->ehplmn_list.plmn != NULL )
    {
      cm_mem_free(ph_sub_config_ptr->ehplmn_list.plmn);
      ph_sub_config_ptr->ehplmn_list.plmn = NULL;

      CM_MSG_HIGH_0("Cleard EHPLMN list");
    }
  }
}

/*==========================================================================

FUNCTION cmph_search_ehplmn_list

DESCRIPTION
  Function that reads EHPLMN list and 

RETURN VALUE
  boolean  Flag indicating whether EHPLMN read
           from the SIM successfully (TRUE) or unsuccessfully(FALSE).

DEPENDENCIES
  None
===========================================================================*/
boolean cmph_search_ehplmn_list
(
  sys_modem_as_id_e_type asubs_id,

  sys_plmn_id_s_type plmn_id
)
{

  cmph_sub_info_s_type             *ph_sub_config_ptr = cmph_get_sub_ptr(asubs_id);
  size_t                           index;
  boolean                          ret_val = FALSE;

  if(ph_sub_config_ptr != NULL &&
     sys_plmn_id_is_valid(plmn_id) &&
     ph_sub_config_ptr->ehplmn_list.length != 0 &&
     ph_sub_config_ptr->ehplmn_list.plmn != NULL )
  {
    for (index = 0; index < ph_sub_config_ptr->ehplmn_list.length; index++)
    {
      if( sys_plmn_match(ph_sub_config_ptr->ehplmn_list.plmn[index], plmn_id) )
      {
        ret_val = TRUE;
        break;
      }
    }
  }

  CM_MSG_HIGH_4("Is PLMN %d %d %d is part of EHPLMN list =%d",
            plmn_id.identity[0], plmn_id.identity[1], plmn_id.identity[2], ret_val);
  return ret_val;
}

/*==========================================================================

FUNCTION cmph_adjust_hybr_pref_for_pending_pref

DESCRIPTION
  Function that adjust's the hybr_pref oc ommand pointer as per switching values

RETURN VALUE
  None

DEPENDENCIES
  None
===========================================================================*/
void cmph_adjust_hybr_pref_for_pending_pref(cm_hybr_pref_e_type hybr_pref)
{
  cmph_s_type     *ph_ptr    = cmph_ptr();
  cm_reply_s_type *reply_ptr = &ph_ptr->device_prop.reply;

  if(cm_reply_is_waiting(reply_ptr) &&
      reply_ptr->cmd_ptr != NULL)
  {
    if(reply_ptr->cmd_ptr->cmd_type == CM_CMD_TYPE_PH)
    {
      cm_ph_cmd_s_type *ph_cmd_ptr = (cm_ph_cmd_s_type *)reply_ptr->cmd_ptr;

      if (ph_cmd_ptr == NULL)
      {
        return;
      }

      if(cmph_is_pref_nochg_set(CMPH_PREF_NOCHG_HYBR_PREF))
      {
        ph_cmd_ptr->info.hybr_pref = hybr_pref;
        CM_MSG_HIGH_1("Changing hybr_pref to %d during the switch", hybr_pref);
      }
    }
  }

}

