/*==========================================================================

FUNCTION cmph_get_pref_reason

DESCRIPTION
  Function returns valid pref reason for pri Q call type

RETURN VALUE
  TRUE/FALSE

DEPENDENCIES
  None
===========================================================================*/
static sd_ss_pref_reas_e_type cmph_get_pref_reason(cm_act_type_e_type    act_type)
{
  sd_ss_pref_reas_e_type pref_reas  = SD_SS_PREF_REAS_ORIG_START_CS;

  switch(act_type)
  {
    case CM_ACT_TYPE_DATA_CALL:
    case CM_ACT_TYPE_GPS:
      pref_reas = SD_SS_PREF_REAS_ORIG_START_PS;
      break;

    case CM_ACT_TYPE_POLICYMAN_RESTRICT:
    case CM_ACT_TYPE_AC_EMERG_MODE:
      pref_reas = SD_SS_PREF_REAS_USER;
      break;

    default:
      break;
  }
  return pref_reas;
}

/*==========================================================================

FUNCTION cmph_is_mcfg_refresh_ongoing

DESCRIPTION
  Checks if there is any MCFG refresh activity happening on given asubs

RETURN VALUE
  boolean Flag indicating whether refresh is ongoing or not

DEPENDENCIES
  None
===========================================================================*/
boolean cmph_is_mcfg_refresh_ongoing(sys_modem_as_id_e_type asubs_id)
{
  if (IS_VALID_PH_SUB_PTR(asubs_id) )
  {
    return (cmph_ptr()->sub_info[asubs_id]->mcfg_state > CMPH_MCFG_STATE_NONE &&
            cmph_ptr()->sub_info[asubs_id]->mcfg_state < CMPH_MCFG_STATE_MAX ) ? TRUE : FALSE;
  }
  return FALSE;
}

/*==========================================================================

FUNCTION cmph_get_subs_with_mcfg_refresh_ongoing

DESCRIPTION
  Checks if there is any MCFG refresh activity happening on any subs

RETURN VALUE
  boolean Flag indicating whether refresh is ongoing or not

DEPENDENCIES
  None
===========================================================================*/
uint8 cmph_get_subs_with_mcfg_refresh_ongoing(void)
{
  unsigned int    i;
  uint8         ret_val = 0;

  for(i = SYS_MODEM_AS_ID_1; cmutil_is_as_id_valid(i); i++)
  {
    ret_val |= (cmph_ptr()->sub_info[i]->mcfg_state > CMPH_MCFG_STATE_NONE &&
                cmph_ptr()->sub_info[i]->mcfg_state < CMPH_MCFG_STATE_MAX ) ? BM(i) : SYS_MODEM_AS_ID_NO_ACTIVE_MASK;
  }

  return ret_val;
}

/*==========================================================================

FUNCTION cmph_set_subs_mcfg_state

DESCRIPTION
  sets MCFG state for given subs

RETURN VALUE
  none

DEPENDENCIES
  None
===========================================================================*/
void cmph_set_subs_mcfg_state(sys_modem_as_id_e_type asubs_id, cmph_subs_mcfg_state_e_type state)
{
  if (IS_VALID_PH_SUB_PTR(asubs_id) )
  {
    CM_MSG_HIGH_3("MCFG_Refresh: as_id %d, updating state from %d to %d", asubs_id,\
                  cmph_ptr()->sub_info[asubs_id]->mcfg_state,\
                  state);
    cmph_ptr()->sub_info[asubs_id]->mcfg_state = state;
  }
}

/*==========================================================================

FUNCTION cmph_get_subs_mcfg_state

DESCRIPTION
  sets MCFG state for given subs

RETURN VALUE
  none

DEPENDENCIES
  None
===========================================================================*/
cmph_subs_mcfg_state_e_type cmph_get_subs_mcfg_state(sys_modem_as_id_e_type asubs_id)
{
  if (IS_VALID_PH_SUB_PTR(asubs_id) )
  {
    return cmph_ptr()->sub_info[asubs_id]->mcfg_state;
  }

  return CMPH_MCFG_STATE_NONE;
}


/*==========================================================================

FUNCTION cmph_update_active_subs_for_mcfg_refresh

DESCRIPTION
  sets MCFG state for given subs

RETURN VALUE
  none

DEPENDENCIES
  None
===========================================================================*/
uint8 cmph_remove_mcfg_refresh_subs(uint8 active_subs)
{
  uint8 ret_mask = active_subs;

  ret_mask &= ~(cmph_get_subs_with_mcfg_refresh_ongoing());

  CM_MSG_HIGH_6("MCFG_Refresh: in %d, out %d, ph %d, user_standby_pref %d, is_standby_pref_buffered %d, any_mcfg %d",
                active_subs, ret_mask, cmph_ptr()->device_prop.msim_prop.active_subs,
                cmph_ptr()->device_prop.msim_prop.user_standby_pref,
                cmph_ptr()->device_prop.msim_prop.is_standby_pref_buffered,
                cmph_get_subs_with_mcfg_refresh_ongoing());
  return ret_mask;
}

