/*===========================================================================

FUNCTION cmph_send_msgr_qmi_cache_reset

DESCRIPTION
 Notify QMI to reset IMS pref chg ind cache upon voice domain pref change to CS only and VOLTE off

DEPENDENCIES

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
void cmph_send_msgr_qmi_cache_reset(sys_modem_as_id_e_type as_id)
{

  cm_qmi_cache_reset_msg_type *qmi_cache_ind = (cm_qmi_cache_reset_msg_type *)cm_mem_malloc
      (sizeof(cm_qmi_cache_reset_msg_type));
  memset(qmi_cache_ind, 0, sizeof(cm_qmi_cache_reset_msg_type));

  cm_msgr_send( MM_CM_IMS_PREF_CACHE_RESET_IND, MSGR_MM_CM,
                (msgr_hdr_s *)qmi_cache_ind, sizeof(cm_qmi_cache_reset_msg_type), as_id );

  cm_mem_free(qmi_cache_ind);
  return;

}

