/*===========================================================================

FUNCTION cmph_force_pref_on_the_fly_by_call_type

DESCRIPTION
  Set mode pref by call type.

DEPENDENCIES
  none

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
void cmph_force_pref_on_the_fly_by_call_type (
    cm_call_type_e_type      call_type,
    cm_srv_type_e_type       srv_type,
    cm_mode_pref_e_type      emerg_mode_pref,
    sys_modem_as_id_e_type   asubs_id,
    cm_act_id_type           act_id
)
{
  cmph_s_type           *ph_ptr          = cmph_ptr();
  /* Point at phone object */

  cmss_s_type           *ss_ptr          = cmss_ptr();
  /* Point at serving system object */

  sd_ss_pref_reas_e_type    force_reason;

  cm_band_pref_e_type       favored_band_pref;
  /* Favored band preference for this call */

  sys_lte_band_mask_e_type  favored_lte_band_pref;
  /* Favored band preference for this call */

  cm_band_pref_e_type       favored_tds_band_pref;
  /* Favored band preference for this call */

  cm_roam_pref_e_type       favored_roam_pref;
  /* Favored roam preference for this call */

  cm_hybr_pref_e_type       favored_hybr_pref;
  /* Favored hybr preference for this call */

  cm_srv_domain_pref_e_type favored_srv_pref;
  /* Favored service domain preference for this call */

  cm_prl_pref_e_type      favored_prl_pref;
  /* Favored prl preference to originate the call */

  cm_activate_code_e_type   otasp_code        = CM_OTASP_ACT_CODE_NONE;
  /* otasp activation code */

  cm_mode_pref_e_type       favored_mode_pref = CM_MODE_PREF_NONE;
  /* Favored mode preference for this call if it is the only call being originated */

  multimode_stack_e_type    stack_id = MM_STACK_0;

  cm_mm_ss_info_sub_prop_s_type *ss_sub_ptr = cmss_get_info_sub_prop(asubs_id);
  cm_mm_ss_info_gen_stack_info_s_type *ss_stack_ptr;
  cm_pref_s_type *pref_ptr = NULL;

  if (cmemg_sub_info_ptr(asubs_id) == NULL)
  {
    return;
  }

  if(ss_sub_ptr == NULL ||
      ss_sub_ptr->stack_info[MM_STACK_0].gen_info == NULL ||
      !IS_VALID_PH_SUB_PTR(asubs_id))
  {
    return;
  }
  ss_stack_ptr = ss_sub_ptr->stack_info[MM_STACK_0].gen_info;

  /* allocate mem for pref_ptr */
  if ((pref_ptr = cm_pref_ptr()) == NULL) return;

  force_reason =(call_type == CM_CALL_TYPE_PS_DATA) ? SD_SS_PREF_REAS_ORIG_START_PS : SD_SS_PREF_REAS_ORIG_START_CS;

  /*---------------------- Set favored srv pref --------------------------*/

  /* Force the service domain preferences in accordance with the
  ** call-type and service domain preferences.
  ** If target doesn't support CS RATs, set the service domain pref to PS only.
  */
  if( call_type ==  CM_CALL_TYPE_PS_DATA  || (!SD_MODE_CONTAIN(ph_ptr->device_prop.hw_capability.mode_capability, (SD_SS_MODE_PREF_TDS_GSM_WCDMA|SD_SS_MODE_PREF_CDMA))))
  {
    favored_srv_pref = CM_SRV_DOMAIN_PREF_PS_ONLY;
  }
  else
  {
    favored_srv_pref = CM_SRV_DOMAIN_PREF_CS_ONLY;
  }

  favored_prl_pref = cmcall_get_favored_prl_pref( call_type );

  /* Get the favored roam preference to be used for the force AMPS.
  */
  favored_roam_pref = cmcall_get_favored_roam_pref( call_type,
                      ss_stack_ptr->sys_mode,
                      ss_stack_ptr->roam_status,
                      CMPH_SS_ROAM_PREF(asubs_id,ph_ptr));

  /*-------------- Set favored mode pref and hybr pref -----------------------*/

  /* This function will write CM_MODE_PREF_NONE into favored_mode_pref
     if it was not able to compute it. Initially, ss is set to main */

  cmcall_set_favored_mode_pref_for_origination ( cmph_map_sub_stk_to_id(asubs_id,MM_STACK_0 ),
                                                 call_type,
                                                 srv_type,
                                                 TRUE,
                                                 CAI_SO_NULL,
                                                 &favored_mode_pref,
                                                 &favored_hybr_pref );
  /*Intersect favoured_mode_pref with emerg_mode_pref to limit E911 scanning to RATs specified in 
   * emerg_mode_pref. If no emerg_mode_pref is specified by AP, default value used is CM_MODE_PREF_NONE
   * and follow legacy behavior 
   */
  if(emerg_mode_pref != CM_MODE_PREF_NONE)
  	{
  		favored_mode_pref = cmcall_misc_get_common_mode_pref(favored_mode_pref, 1, emerg_mode_pref);
  	}
  
  /*------------------------ Get stack------------------------------------*/

#ifdef FEATURE_CM_LTE
  /* Pass mode pref and hybr pref to get ss. Mode usage is not used in this function.
  ** So just pass CM_CC_MODE_PREF_ANY
  */
  stack_id = cmemg_determine_ss_for_origination( favored_hybr_pref, asubs_id);

#endif
  /* Get the favored band preference to be used for this call-type and
  ** service-type.
  */
  favored_band_pref = cmcall_get_favored_band_pref( call_type,
                      srv_type,
                      CMPH_SS_BAND_PREF(asubs_id, ph_ptr));
  favored_lte_band_pref = cmcall_get_favored_lte_band_pref( call_type,
                          CMPH_SS_LTE_BAND_PREF(asubs_id, ph_ptr));
  favored_tds_band_pref = cmcall_get_favored_tds_band_pref( call_type,
                          CMPH_SS_TDS_BAND_PREF(asubs_id, ph_ptr));

  memscpy(pref_ptr, sizeof(cm_pref_s_type),
          &(ph_ptr->sub_info[asubs_id]->pref_info), sizeof(cm_pref_s_type));
  pref_ptr->pref_term               = CM_PREF_TERM_CM_1_CALL_PLUS;
  pref_ptr->network_sel_mode_pref   = CM_NETWORK_SEL_MODE_PREF_NONE;
  pref_ptr->prl_pref                = favored_prl_pref;
  pref_ptr->roam_pref               = favored_roam_pref;
  pref_ptr->hybr_pref               = favored_hybr_pref;
  pref_ptr->mode_pref               = favored_mode_pref;
  pref_ptr->band_pref               = favored_band_pref;
  pref_ptr->tds_band_pref           = favored_tds_band_pref;
  pref_ptr->lte_band_pref           = favored_lte_band_pref;
  pref_ptr->srv_domain_pref         = favored_srv_pref;
  pref_ptr->csg_id                  = SYS_CSG_ID_INVALID;
  pref_ptr->csg_rat                 = SYS_RAT_NONE;

  CM_MSG_HIGH_6(">>PH FORCE_PREF: sub %d stk %d reason %d mode_pref %d hybr_pref %d domain_pref %d",
                asubs_id, stack_id, force_reason, favored_mode_pref, favored_hybr_pref, favored_srv_pref);

  (void)cmph_force_pref_on_the_fly_stack(
    cmph_map_sub_stk_to_id(asubs_id,stack_id),
    force_reason,
    cmtask_map_call_type_to_act_type(call_type),
    pref_ptr,
    otasp_code,
             act_id,
    CM_ACT_UPDATE_REAS_ACT_START,
    TRUE,
    cmph_get_acq_pri_order_per_sub(asubs_id),
    CM_DEFAULT_VALUE);

  cm_mem_free (pref_ptr);
} /* cmemg_force_pref_on_the_fly_by_call_type */

#ifdef FEATURE_CM_LTE
/*===========================================================================

FUNCTION cmph_force_pref_on_the_fly_by_stk_id

DESCRIPTION
  Set mode pref by stack id.

DEPENDENCIES
  none

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
void cmph_force_pref_on_the_fly_by_stk_id (
  sys_modem_as_id_e_type   asubs_id,
  multimode_stack_e_type   stk_id,
  cm_mode_pref_e_type      emerg_mode_pref
)
{
  mm_sub_stk_id_s_type local_mm_id = cmph_map_sub_stk_to_id(asubs_id,stk_id);
  cm_orig_q_s_type        *top_ptr = cmtask_orig_para_get_top(local_mm_id);
  cm_pref_s_type *pref_ptr = NULL;
  cmph_sub_info_s_type *ph_sub_ptr = cmph_get_sub_ptr(asubs_id);
  cmph_s_type                      *ph_ptr = cmph_ptr();

  if (top_ptr == NULL || ph_sub_ptr == NULL)
  {
    sys_err_fatal_null_ptr_exception();
    return;
  }

  if ((pref_ptr = cm_pref_ptr()) == NULL) return;

  memscpy(pref_ptr, sizeof(cm_pref_s_type),
          &(ph_sub_ptr->pref_info), sizeof(cm_pref_s_type));

  pref_ptr->pref_term              = CM_PREF_TERM_CM_1_CALL_PLUS;
  pref_ptr->network_sel_mode_pref  = CM_NETWORK_SEL_MODE_PREF_NONE;
  pref_ptr->prl_pref               = CM_PRL_PREF_ANY;
  pref_ptr->roam_pref              = CM_ROAM_PREF_ANY;
  pref_ptr->hybr_pref              = CMPH_SS_HYBR_PREF(asubs_id, ph_ptr);
  pref_ptr->band_pref              = CM_BAND_PREF_ANY;
  pref_ptr->tds_band_pref          = CM_BAND_PREF_TDS_ANY;
  pref_ptr->lte_band_pref          = SYS_LTE_BAND_MASK_CONST_ANY;
  pref_ptr->srv_domain_pref        = CM_SRV_DOMAIN_PREF_CS_ONLY;
  pref_ptr->csg_id                 = SYS_CSG_ID_INVALID;
  pref_ptr->csg_rat                = SYS_RAT_NONE;

  /*Intersect favoured_mode_pref with emerg_mode_pref to limit E911 scanning to RATs specified in 
   * emerg_mode_pref. If no emerg_mode_pref is specified by AP, default value used is CM_MODE_PREF_NONE
   * and follow legacy behavior 
   */
  if(emerg_mode_pref != CM_MODE_PREF_NONE)
  {
    pref_ptr->mode_pref = cmcall_misc_get_common_mode_pref(top_ptr->orig->orig_mode_pref, 1, emerg_mode_pref);
  }
  else
  {
    pref_ptr->mode_pref              = top_ptr->orig->orig_mode_pref;
  }

  CM_MSG_HIGH_2(">>PH FORCE_PREF: force pref on stack %d sub %d", stk_id, asubs_id);
  (void)cmph_force_pref_on_the_fly_stack(
    local_mm_id,
    SD_SS_PREF_REAS_ORIG_START_CS,
    cmtask_map_call_type_to_act_type(CM_CALL_TYPE_EMERGENCY),
    pref_ptr,
    CM_OTASP_ACT_CODE_NONE,
    (cm_act_id_type)cmemg_sub_info_ptr(asubs_id),
    CM_ACT_UPDATE_REAS_ACT_START,
    TRUE,
    cmph_get_acq_pri_order_per_sub(asubs_id),
    CM_DEFAULT_VALUE);
  cm_mem_free (pref_ptr);

}
#endif

