#if defined(FEATURE_IP_CALL)
/*==========================================================================

FUNCTION cmph_single_lte_trigger_ims_dereg

DESCRIPTION
  For single-LTE configuration during DDS switch. Evaluates the
  sub on which to trigger IMS deregistration.

RETURN VALUE
  The sub for which to trigger IMS deregistration

DEPENDENCIES
  None

===========================================================================*/
static sys_modem_as_id_e_type cmph_single_lte_trigger_ims_dereg(
  cm_ph_cmd_s_type       *ph_cmd_ptr,
  sys_modem_as_id_e_type  curr_data_subs
)
{
  cmph_s_type           *ph_ptr      = cmph_ptr();

  if(cmph_is_gw_subsc_avail(curr_data_subs) &&
      (ph_ptr->device_prop.msim_prop.active_subs & BM(curr_data_subs)) &&
      !cmph_is_mcfg_refresh_ongoing(curr_data_subs) &&
      cmph_is_ims_capable_on_sub(curr_data_subs))
  {
    CM_MSG_HIGH_1("CM->IMS: DDS_SWITCH: send IMS dereg for sub %d", curr_data_subs);
    cmipapp_send_srv_domain(CM_PS_DETACH_BY_MMODE_DDS_SWITCH, TRUE, curr_data_subs);

    if(cmipapp_is_wait_on_srv_domain_cnf(CM_PS_DETACH_BY_MMODE_DDS_SWITCH, curr_data_subs))
    {
      cmph_ims_dereg_is_sent(curr_data_subs, TRUE);

      CM_MSG_HIGH_1("CM->IMS: DDS_SWITCH: wait for dereg cnf for sub %d", curr_data_subs);
      cm_reply_set(&ph_ptr->device_prop.reply,
                   (cm_cmd_type *)ph_cmd_ptr,
                   CM_IP_APP_ALLAPPS_SRV_DOM_CNF,
                   CMPH_MAX_IPAPP_DEREG_TIME);

      return curr_data_subs;
    }
  }

  return SYS_MODEM_AS_ID_NONE;
}

/*==========================================================================

FUNCTION cmph_dual_lte_trigger_ims_dereg

DESCRIPTION
  For dual-LTE configuration during DDS switch. Evaluates the sub on which
  to trigger IMS deregistration.

  For DDS switch with both subs IMS capable, get sandbox policy
  to determine subs with capability change. IMS deregistration is
  needed for all subs with capability change when any of the changed RATs
  are in the current preference. If both subs need IMS deregistration, this
  function will be called twice to deregister one sub at a time.

RETURN VALUE
  The sub for which to trigger IMS deregistration

DEPENDENCIES
  None

===========================================================================*/
static sys_modem_as_id_e_type cmph_dual_lte_trigger_ims_dereg(
  cm_ph_cmd_s_type       *ph_cmd_ptr,
  sys_modem_as_id_e_type  new_dds_sub,
  cm_dds_cause_e_type     dds_switch_type
)
{
  cmph_s_type           *ph_ptr = cmph_ptr();
  sys_modem_as_id_e_type sub    = SYS_MODEM_AS_ID_NONE;
  sys_modem_as_id_e_type other_sub    = SYS_MODEM_AS_ID_NONE;
  mm_sub_stk_id_s_type mm_id ;  
  cm_orig_q_s_type	*ph_orig_ptr = NULL;
  boolean                 send_no_ps_detach_on_dds = FALSE;

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* Check for subs with capability change
  */
  if(!ph_ptr->device_prop.is_new_pm_subs_cap_checked)
  {
    ph_ptr->device_prop.ims_dereg_subs = cmpmprx_get_subs_for_ims_dereg(
                                           ph_ptr->device_prop.msim_prop.active_subs,
                                           new_dds_sub,
                                           dds_switch_type);
    /* If CM does not need to tell IMS to dereg on the DDS sub due to PS detach,
    ** set a flag so CM informs CM_NO_PS_DETACH_BY_MMODE_DDS_SWITCH to IMS on
    ** the DDS sub (IMS may dereg or send the CNF immediately for this cause)
    */
    if(!(ph_ptr->device_prop.ims_dereg_subs &
           BM(ph_ptr->device_prop.msim_prop.default_data_subs)))
    {
      send_no_ps_detach_on_dds = TRUE;
    }

    ph_ptr->device_prop.is_new_pm_subs_cap_checked = TRUE;
  }

  /* Send IMS deregistration and set reply info
  */
  mm_id = cmph_map_sub_stk_to_id(ph_ptr->device_prop.msim_prop.default_data_subs,MM_STACK_0);
  ph_orig_ptr = cmtask_orig_para_get_top(mm_id);
  
  if(ph_orig_ptr == NULL)
  {
     return SYS_MODEM_AS_ID_NONE;
  }

  // Send on DDS first
  if(cmph_is_gw_subsc_avail(ph_ptr->device_prop.msim_prop.default_data_subs) &&
      (ph_ptr->device_prop.msim_prop.active_subs &
         BM(ph_ptr->device_prop.msim_prop.default_data_subs)) &&
      ((ph_ptr->device_prop.ims_dereg_subs &
          BM(ph_ptr->device_prop.msim_prop.default_data_subs))
         ||
         send_no_ps_detach_on_dds) &&
      !cmph_is_mcfg_refresh_ongoing(ph_ptr->device_prop.msim_prop.default_data_subs) &&
       ph_orig_ptr->act_type ==CM_ACT_TYPE_PH_OBJ)
  {
    CM_MSG_HIGH_2("CM->IMS: DDS_SWITCH: send IMS dereg for DDS sub %d, no_ps_detach %d",
                  ph_ptr->device_prop.msim_prop.default_data_subs,
                  send_no_ps_detach_on_dds);
    if(send_no_ps_detach_on_dds)
    {
      cmipapp_send_srv_domain(CM_NO_PS_DETACH_BY_MMODE_DDS_SWITCH, TRUE, ph_ptr->device_prop.msim_prop.default_data_subs);
    }
    else
    {
      cmipapp_send_srv_domain(CM_PS_DETACH_BY_MMODE_DDS_SWITCH, TRUE, ph_ptr->device_prop.msim_prop.default_data_subs);
    }
    ph_ptr->device_prop.ims_dereg_subs &= ~(BM(ph_ptr->device_prop.msim_prop.default_data_subs));

    if(cmipapp_is_wait_on_srv_domain_cnf(CM_NO_PS_DETACH_BY_MMODE_DDS_SWITCH,
                            ph_ptr->device_prop.msim_prop.default_data_subs) ||
      cmipapp_is_wait_on_srv_domain_cnf(CM_PS_DETACH_BY_MMODE_DDS_SWITCH,
                            ph_ptr->device_prop.msim_prop.default_data_subs))
    {
      if(!send_no_ps_detach_on_dds)
      {
        cmph_ims_dereg_is_sent(ph_ptr->device_prop.msim_prop.default_data_subs, TRUE);
      }
      CM_MSG_HIGH_1("CM->IMS: DDS_SWITCH: wait for dereg cnf for sub %d", ph_ptr->device_prop.msim_prop.default_data_subs);
      cm_reply_set(&ph_ptr->device_prop.reply,
                     (cm_cmd_type *)ph_cmd_ptr,
                     CM_IP_APP_ALLAPPS_SRV_DOM_CNF,
                     CMPH_MAX_IPAPP_DEREG_TIME);

      return ph_ptr->device_prop.msim_prop.default_data_subs;
    }
  }

  other_sub = cmph_get_other_sub(ph_ptr->device_prop.msim_prop.default_data_subs);
  mm_id = cmph_map_sub_stk_to_id(other_sub,MM_STACK_0);
  ph_orig_ptr = cmtask_orig_para_get_top(mm_id);

  if(ph_orig_ptr == NULL)
  {
     return SYS_MODEM_AS_ID_NONE;
  }


  if(cmph_is_gw_subsc_avail(other_sub) &&
      (ph_ptr->device_prop.msim_prop.active_subs & BM(other_sub)) &&
      (ph_ptr->device_prop.ims_dereg_subs & BM(other_sub))&&
      !cmph_is_mcfg_refresh_ongoing(other_sub) &&
        ph_orig_ptr->act_type ==CM_ACT_TYPE_PH_OBJ)
  {
    CM_MSG_HIGH_1("CM->IMS: DDS_SWITCH: send IMS dereg for nDDS sub %d", other_sub);
    cmipapp_send_srv_domain(CM_PS_DETACH_BY_MMODE_DDS_SWITCH, TRUE, other_sub);

    ph_ptr->device_prop.ims_dereg_subs &= ~(BM(other_sub));

    if(cmipapp_is_wait_on_srv_domain_cnf(CM_PS_DETACH_BY_MMODE_DDS_SWITCH, other_sub))
    {
      cmph_ims_dereg_is_sent(other_sub, TRUE);

      CM_MSG_HIGH_1("CM->IMS: DDS_SWITCH: wait for dereg cnf for sub %d", other_sub);
      cm_reply_set(&ph_ptr->device_prop.reply,
                   (cm_cmd_type *)ph_cmd_ptr,
                   CM_IP_APP_ALLAPPS_SRV_DOM_CNF,
                   CMPH_MAX_IPAPP_DEREG_TIME);

      return other_sub;
    }
  }

  /* All IMS deregistration is done, reset dereg info
  */
  ph_ptr->device_prop.ims_dereg_subs = SYS_MODEM_AS_ID_NO_ACTIVE_MASK;
  ph_ptr->device_prop.is_new_pm_subs_cap_checked = FALSE;

  return SYS_MODEM_AS_ID_NONE;
}
#endif

/*==========================================================================

FUNCTION cmph_ims_dereg_is_sent

DESCRIPTION
  Update ims_dereg_is_sent flag.

RETURN VALUE
  None

DEPENDENCIES
  None

===========================================================================*/
void cmph_ims_dereg_is_sent(
  sys_modem_as_id_e_type  asubs_id,
  boolean                 dereg_is_sent
)
{
  cmph_sub_info_s_type *ph_sub_ptr = cmph_get_sub_ptr(asubs_id);

  if (!ph_sub_ptr)
  {
    return;
  }

  ph_sub_ptr->ps_pref.dereg_is_sent = dereg_is_sent;
}

/*==========================================================================

FUNCTION cmph_send_detach_comp

DESCRIPTION
  Send CM_PS_DETACH_BY_MMODE_COMPLETE so that IMS can perform re-reg later.

RETURN VALUE
  None

DEPENDENCIES
  None

===========================================================================*/
void cmph_send_detach_comp(
  sys_modem_as_id_e_type  asubs_id
)
{
  #if defined(FEATURE_IP_CALL)
  cmph_sub_info_s_type *ph_sub_ptr = cmph_get_sub_ptr(asubs_id);

  if(ph_sub_ptr == NULL) return;
  CM_MSG_HIGH_1_ASID("CM->IMS: DDS_SWITCH: send MMODE_COMPLETE for re-reg",
                         asubs_id);
  cmipapp_send_srv_domain (CM_PS_DETACH_BY_MMODE_COMPLETE, FALSE, asubs_id);
  cmph_ims_dereg_is_sent(asubs_id, FALSE);
  ph_sub_ptr->volte_sub_info.is_ps_detach_comp_pending = FALSE;

  #endif
}
