#ifdef FEATURE_MMODE_DUAL_SIM
/*===========================================================================

FUNCTION cmph_process_me_blocked_status_ind

DESCRIPTION
  This function process ME blocked status ind from NAS

DEPENDENCIES

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/

void cmph_process_me_blocked_status_ind( const cm_me_blocked_status_ind_s_type  *me_blocked_status_ind_ptr)
{
  sys_modem_as_id_e_type as_id = SYS_MODEM_AS_ID_NONE;
  cmph_sub_info_s_type *ph_sub_ptr = NULL;
  
  if (me_blocked_status_ind_ptr == NULL)
  {
    return;
  }
  as_id = me_blocked_status_ind_ptr->as_id;
  if (!cmutil_is_as_id_valid(me_blocked_status_ind_ptr->as_id))
  {
    return;
  }
  ph_sub_ptr = cmph_get_sub_ptr(as_id);
  if (ph_sub_ptr == NULL)
  {
    return;
  }

  CM_MSG_HIGH_3("ME_BLOCKED: me_blocked_status as_id %d, status %d, curr_status %d",
    as_id, me_blocked_status_ind_ptr->is_me_blocked, ph_sub_ptr->block_reason);

  // Block case when NAS sends reject cause #6
  if (me_blocked_status_ind_ptr->is_me_blocked == TRUE && cmph_get_blocked_sub() == SYS_MODEM_AS_ID_NONE)
  {
    cmph_sub_info_s_type *other_ph_sub_ptr = NULL;
    sys_modem_as_id_e_type other_sub       = cmph_get_other_sub(as_id);
    
    ph_sub_ptr->block_reason = CMPH_BLOCK_REASON_ILLEGAL_ME;
    other_ph_sub_ptr = 
      cmutil_is_as_id_valid(other_sub)?cmph_get_sub_ptr(other_sub):NULL;

    if (other_ph_sub_ptr != NULL)
    {
      other_ph_sub_ptr->block_reason = CMPH_BLOCK_REASON_ILLEGAL_ME_DUE_TO_OTHER_SUB;
      cm_ac_cmd_control_nw_access(NULL, NULL, CM_CLIENT_ID_ANONYMOUS, 
                                  CM_AC_CMD_EMERGENCY_ONLY, CM_AC_REASON_ME_BLOCKED, other_sub );

    }

    cmph_event(CM_PH_EVENT_SUB_BLOCKED_STATUS);
  }
  // Unblock case when NAS detects Sub is unblocked
  else if (me_blocked_status_ind_ptr->is_me_blocked == FALSE && cmph_get_blocked_sub() != SYS_MODEM_AS_ID_NONE)
  {
    cmph_sub_info_s_type *other_ph_sub_ptr = NULL;
    sys_modem_as_id_e_type other_sub       = cmph_get_other_sub(as_id);

    // Err Fatal when NAS sends block on one sub and unblock on other
    if (ph_sub_ptr->block_reason != CMPH_BLOCK_REASON_ILLEGAL_ME)
    {
      CM_ERR_FATAL_2("ME_BLOCKED: unblock received on incorrect subs, received on as_id %d, block_state %d, \
        other_sub_block_state %d",as_id, ph_sub_ptr->block_reason);
    }
    else
    {
      ph_sub_ptr->block_reason = CMPH_BLOCK_REASON_NONE;
      other_ph_sub_ptr = 
        cmutil_is_as_id_valid(other_sub)?cmph_get_sub_ptr(other_sub):NULL;

      if (other_ph_sub_ptr != NULL)
      {
        other_ph_sub_ptr->block_reason = CMPH_BLOCK_REASON_NONE;
        cm_ac_cmd_control_nw_access(NULL, NULL, CM_CLIENT_ID_ANONYMOUS, 
                                    CM_AC_CMD_NORMAL_OPERATION, CM_AC_REASON_ME_BLOCKED, other_sub );

      }
    }
    cmph_event(CM_PH_EVENT_SUB_BLOCKED_STATUS);
  }

}
#endif
/*===========================================================================

FUNCTION cmph_get_blocked_sub

DESCRIPTION
  This function returns subscription which is blocked by network due to reason 6

DEPENDENCIES

RETURN VALUE
  sys_modem_as_id_e_type

SIDE EFFECTS
  none

===========================================================================*/

sys_modem_as_id_e_type cmph_get_blocked_sub(void)
{
  cmph_sub_info_s_type *ph_sub_ptr = NULL;
  if (!cmph_is_msim())
  {
    return SYS_MODEM_AS_ID_NONE;
  }
  else
  {
   sys_modem_as_id_e_type asubs_id;

    for ( asubs_id = SYS_MODEM_AS_ID_1;
          cmutil_is_as_id_valid(asubs_id);
          asubs_id++ )
    {
      ph_sub_ptr = cmph_get_sub_ptr(asubs_id);
      if (ph_sub_ptr != NULL && ph_sub_ptr->block_reason == CMPH_BLOCK_REASON_ILLEGAL_ME)
      {
        return asubs_id;
      }
    }
  }
  return SYS_MODEM_AS_ID_NONE;
}

/*==========================================================================

FUNCTION cmph_get_volte_state

DESCRIPTION
  Return the value for is_volte_on for the specified sub.

RETURN VALUE
  Boolean

DEPENDENCIES
  None

===========================================================================*/
boolean cmph_get_volte_state(
  sys_modem_as_id_e_type  asubs_id
)
{
  cmph_s_type *ph_ptr = cmph_ptr();
  
  if(asubs_id >= SYS_MODEM_AS_ID_1 &&
    asubs_id < ARR_SIZE(ph_ptr->sub_info) &&
    asubs_id < MAX_SIMS)
  {
    if(ph_ptr->sub_info[asubs_id] != NULL)
    {
      return ph_ptr->sub_info[asubs_id]->volte_sub_info.is_volte_on;
    }
  }

  return FALSE;
}


/*===========================================================================

FUNCTION cmph_is_periodic_srch_active_in_ll

DESCRIPTION
  This function will determine if there is actual periodic search active in lower layer and CM is 
  waiting for list cnf. 
  If there is a periodic search in CM but timer for mplmn search is still running, the function should 
  return FALSE.
  If there are any other MPLMN search such as one-timer search, CSG search or mmode internal search
  ongoing, the function should return FALSE.

DEPENDENCIES
  Phone object must have already been initialized with
  cmph_init().

RETURN VALUE
  Boolean

SIDE EFFECTS
  None

===========================================================================*/
boolean cmph_is_periodic_srch_active_in_ll(
  sys_modem_as_id_e_type    asubs_id
)
{
  cmph_s_type *ph_ptr = cmph_ptr();
  cmph_sub_info_s_type *ph_net_sub_ptr = cmph_get_net_sub_ptr(asubs_id);

  if(!ph_ptr->device_prop.pf_scan_info ||
     !cmutil_is_periodic_manual_search() ||
     !ph_net_sub_ptr)
  {
    return FALSE;
  }

  /* NO any search on the sub */
  if (ph_ptr->device_prop.pf_scan_info->asubs_id != asubs_id ||
     !cmph_is_get_networks_ongoing(asubs_id) ||
     cmph_ptr()->device_prop.mm_id_for_get_networks.asubs_id == SYS_MODEM_AS_ID_NONE
  )
  {
    return FALSE;
  }

  /* csg search or internal mplmn search ongoing */
  if((ph_net_sub_ptr->pref_info.network_list_type == CM_NETWORK_LIST_CSG ||
     ph_net_sub_ptr->pref_info.network_list_type == CM_NETWORK_LIST_CSG_USER ||
     ph_net_sub_ptr->pref_info.network_list_type == CM_NETWORK_LIST_CSG_SELECTION_APP ||
     (sd_is_manual_bst_valid(ph_ptr->device_prop.mm_id_for_get_networks.asubs_id) && 
      ph_net_sub_ptr->pref_info.ignore_manual_bst)
    )
  )
  {
    return FALSE;
  }
  
  return TRUE;
}

/*===========================================================================

FUNCTION cmph_is_high_prio_man_srch

DESCRIPTION
  Determine if the MPLMN search is high priority search.  
  MPLMN search is high priority if it is one-time search.
  MPLMN search is high prority if priority is high for periodic search.

DEPENDENCIES
  None

RETURN VALUE
  Boolean
  
SIDE EFFECTS
  none

===========================================================================*/
boolean cmph_is_high_prio_man_srch(
  sys_periodic_frequency_scan_info_s_type  *pf_scan_info
)
{
  if (!pf_scan_info) 
  {
    return TRUE;
  }

  if (pf_scan_info->search_periodicity == 0) 
  {  
    return TRUE;
  }
  
  if(pf_scan_info->priority == SYS_SRCH_PRIORITY_HIGH)
  {
    return TRUE;
  }
  
  return FALSE;
}

/*===========================================================================

FUNCTION cmph_pfscan_cmd_err_cleanup

DESCRIPTION
  This function will cleanup MPLMN pf_scan information if the get network is rejected.

DEPENDENCIES
  Phone object must have already been initialized with
  cmph_init().

RETURN VALUE
  None

SIDE EFFECTS
  None

===========================================================================*/
static void cmph_pfscan_cmd_err_cleanup(
  sys_modem_as_id_e_type    asubs_id
)
{
  cmph_s_type *ph_ptr = cmph_ptr();
  cmph_sub_info_s_type *ph_net_sub_ptr = cmph_get_net_sub_ptr(asubs_id);
  cm_network_list_type_e_type temp_network_list_type = CM_NETWORK_LIST_NONE;

  if(!ph_ptr->device_prop.pf_scan_info ||
     !ph_net_sub_ptr)
  {
    return;
  }

  if(ph_ptr->device_prop.pf_scan_info->asubs_id != asubs_id ||
     !cmutil_is_periodic_manual_search())
  {
    return;
  }

  temp_network_list_type = ph_net_sub_ptr->pref_info.network_list_type;

  ph_net_sub_ptr->pref_info.network_list_type = ph_ptr->device_prop.pf_scan_info->network_list_type;
  cmph_event_per_subs( CM_PH_EVENT_TERMINATE_GET_NETWORKS, asubs_id);
  ph_net_sub_ptr->pref_info.network_list_type = temp_network_list_type;
    
  cmph_reset_network_pref(asubs_id, FALSE);
  ph_ptr->device_prop.pf_scan_info = NULL;
}

/*===========================================================================

@FUNCTION cmph_is_rat_bal_allowed

@DESCRIPTION
  TRUE: 
    When rat bal is enabled:
    - if single sim or dual LTE. 
    - if primary subs is Multimode and Active

  FALSE:
  - Otherwise.

@DEPENDENCIES
  None

@SIDE EFFECTS
  None

===========================================================================*/
boolean cmph_is_rat_bal_allowed(
  sys_modem_as_id_e_type  asubs_id
)
{
  if (IS_VALID_PH_SUB_PTR(asubs_id) &&
        cmph_ptr()->sub_info[asubs_id]->ef_rat.is_rat_bal
  )
  {
    if(!cmph_is_msim() || cmph_is_dual_lte())
    {
      return TRUE;
    }
    else if(asubs_id == SYS_MODEM_AS_ID_1)
    {
      return (cm_is_multimode_subs(SYS_MODEM_AS_ID_1) &&\
              (cmph_ptr()->device_prop.msim_prop.active_subs == SYS_MODEM_AS_ID_1_MASK));
    }
    else
    {
      return FALSE;
    }
  }
  else
  {
    return FALSE;
  }
}

/*===========================================================================

@FUNCTION cmph_update_sp_special_priority_mode

@DESCRIPTION
  Indicate to TRM layer if special TRM mapping is needed for MMS or Wifi call activity

  Start Conditions:
  - For MMS/data activity on non DDS sub, start the special mapping on the DDS sub
  - For MO/MT wifi call, start the special mapping on the call sub

  End Condition:
  - For MMS/data activity end on the non DDS sub, end the special mapping on the DDS sub
  - For DDS switch, end the special mapping on the DDS sub
  - For MO/MT wifi call end, end the special mapping on the call sub
  - For MO/MT wifi call handover to LTE, end the special mapping on the call sub

@DEPENDENCIES
  None

@SIDE EFFECTS
  None

===========================================================================*/
void cmph_update_sp_special_priority_mode(
  boolean                 is_mms_activity,
    /* Indicates if current activity is MMS or Wifi related */

  boolean                 is_start,
    /* Indicates if the special mapping should be started or stopped */

  sys_modem_as_id_e_type  asubs_id
)
{
  cmph_sub_info_s_type *ph_sub_ptr = cmph_get_sub_ptr(asubs_id);

  if(ph_sub_ptr != NULL)
  {
    CM_MSG_HIGH_5("update_sp_special_priority_mode: is_mms_act %d, is_start %d, sub %d, mms_on %d, wifi_on %d",
                  is_mms_activity, is_start, asubs_id,
                  ph_sub_ptr->is_sp_special_priority_mode_mms,
                  ph_sub_ptr->is_sp_special_priority_mode_wifi);

    /* Special TRM mapping may need to be started */
    if(is_start)
    {
      /* Inform TRM to start the special mapping if we did not already inform them
          ** to start it
          */
      if(ph_sub_ptr->is_sp_special_priority_mode_mms == FALSE &&
         ph_sub_ptr->is_sp_special_priority_mode_wifi == FALSE)
      {
        cmph_send_sp_special_priority_mode(is_start, asubs_id);
      }

      /* Set a flag for the activity which is ongoing
          */
      if(is_mms_activity)
      {
        ph_sub_ptr->is_sp_special_priority_mode_mms = TRUE;
      }
      else
      {
        ph_sub_ptr->is_sp_special_priority_mode_wifi = TRUE;
      }
    }
    /* Special TRM mapping may need to be stopped */
    else
    {
      if(is_mms_activity)
      {
        /* Inform TRM to stop the special mapping if it does not need to remain on for
        ** wifi activity
        */
        if(ph_sub_ptr->is_sp_special_priority_mode_mms == TRUE &&
           ph_sub_ptr->is_sp_special_priority_mode_wifi == FALSE)
        {
          cmph_send_sp_special_priority_mode(is_start, asubs_id);
        }

        /* Reset the MMS activity flag
              */
        ph_sub_ptr->is_sp_special_priority_mode_mms = FALSE;
      }
      else
      {
        /* Inform TRM to stop the special mapping if it does not need to remain on for
        ** MMS activity
        */
        if(ph_sub_ptr->is_sp_special_priority_mode_mms == FALSE &&
           ph_sub_ptr->is_sp_special_priority_mode_wifi == TRUE)
        {
          cmph_send_sp_special_priority_mode(is_start, asubs_id);
        }

        /* Reset the Wifi activity flag
        */
        ph_sub_ptr->is_sp_special_priority_mode_wifi = FALSE;
      }
    }
  }
  else
  {
    CM_MSG_HIGH_0("update_sp_special_priority_mode: ERROR, ph ptr is NULL");
  }
}

/*===========================================================================

@FUNCTION cmph_send_sp_special_priority_mode

@DESCRIPTION
  Sends the special TRM mapping request to TRM

@DEPENDENCIES
  None

@SIDE EFFECTS
  None

===========================================================================*/
void cmph_send_sp_special_priority_mode(
  boolean                 is_start,
    /* Indicates if the special mapping should be started or stopped */

  sys_modem_as_id_e_type  asubs_id
)
{
  sp_special_mode_input_type   sp_input;
  sp_special_mode_output_type  sp_output;

  CM_MSG_HIGH_2("send_sp_special_priority_mode: sending TRM mode update on sub %d, start %d",
                asubs_id, is_start);

  sp_input.asid = asubs_id;
  sp_input.start_operation = is_start;
  sp_update_special_priority_mapping(&sp_input, &sp_output);
}

#ifdef FEATURE_CM_LTE
/*===========================================================================

FUNCTION cmph_reg_send_block_plmn_reset_req

DESCRIPTION
  This function sends PLMN block req to NAS with type RESET and cause
  VOICE_NOT_AVAILABLE. NAS will remove all backoff forbidden PLMNs that
  were added with cause VOICE_NOT_AVAILABLE.

DEPENDENCIES

RETURN VALUE

SIDE EFFECTS

===========================================================================*/
void cmph_reg_send_block_plmn_reset_req(

  sys_modem_as_id_e_type            cmd_subs,

  sys_block_plmn_cause_e_type       cause
)
{
  reg_cmd_type                *reg_ptr;

  /* Get reg cmd. buffer and populate params.*/
  reg_ptr =  cm_reg_get_buf_else_err_fatal( CM_BLOCK_PLMN_REQ );

  /* Fill in parameters. */
  reg_ptr->cmd.cm_block_plmn_req.type = SYS_BLOCK_PLMN_RESET;
  reg_ptr->cmd.cm_block_plmn_req.as_id = cmd_subs;
  reg_ptr->cmd.cm_block_plmn_req.cause = cause;

  CM_MSG_HIGH_2("CM->NAS: Reset blocked PLMNs due to voice not avail as_id %d, cause %d",
                reg_ptr->cmd.cm_block_plmn_req.as_id,
                cause);

  /* Send the request to NAS */
  cm_reg_send_cmd( reg_ptr );

}
#endif

/*===========================================================================

FUNCTION cmph_check_if_clnup_on_non1x_sub

DESCRIPTION
  This function checks if the cdma sub NA event is reported on non-1x sub in DSDS configuration and if clean up 
  is needed on non 1x sub. 
  
DEPENDENCIES
  none

RETURN VALUE
  TRUE: Either if CDMA sub na is received on 1x sub or gwl subscription na is received on non-1x sub
  FALSE: If CDMA sub na is received on non-1x sub

SIDE EFFECTS
  none

===========================================================================*/
boolean                       cmph_check_if_clnup_on_non1x_sub(
  cm_subscription_status_e_type                 gwl_sub_not_avail_status,
  cm_subscription_status_e_type                 cdma_sub_not_avail_status,   
  sys_modem_as_id_e_type                  asubs_id
)
{
  cmph_s_type *ph_ptr = cmph_ptr();

  /* In DSDS config, If the subscription CSIM Not available event is being processed on Non-1x sub, then we do not need clean up with IMS and DS.
   ** Clean up would be needed only when GW sub na is received on Non-1x sub. 
   ** Cases are 1. GW sub available and CDMA sub na on non 1x sub - Cln up not needed
   ** Cases are 2. GW sub not available and CDMA sub na on non 1x sub - Cln up needed
   ** Cases are 3. GW sub not  available and CDMA sub available on  non-1x dds - Cln up needed 
   */
   CM_MSG_HIGH_4("PH_PROC: cmph_check_if_clnup_on_non1x_sub : gwl %d, cdma %d , active_subs %d, 1x sub %d",
                          gwl_sub_not_avail_status,
                          cdma_sub_not_avail_status,
                          ph_ptr->device_prop.msim_prop.active_subs,
                          cmmsc_get_1x_sub());
    
   
  if((asubs_id != SYS_MODEM_AS_ID_NONE) && (cmmsc_get_1x_sub() != asubs_id ) && 
	( ph_ptr->device_prop.msim_prop.active_subs == ( SYS_MODEM_AS_ID_1_MASK | SYS_MODEM_AS_ID_2_MASK )) &&
  	(gwl_sub_not_avail_status == CM_SUBSCRIPTION_STATUS_NO_CHANGE) &&
  	(cdma_sub_not_avail_status == CM_SUBSCRIPTION_STATUS_CHANGE))
  {
    CM_MSG_HIGH_0("NO_CLNUP: CDMA Sub Na received on Non-1x sub");
  	return FALSE;
  }

  return TRUE;	
} /*cmph_check_if_clnup_on_non1x_sub*/

/*===========================================================================

@FUNCTION cmph_is_trm_in_fallback_state

@DESCRIPTION
  Queries TRM to get the current fallback state for the non-DDS sub.
  Returns TRUE if TRM indicates a valid fallback state.

===========================================================================*/
boolean cmph_is_trm_in_fallback_state()
{
  boolean ret = FALSE;
  trm_get_info_input_type *input = (trm_get_info_input_type*)cm_mem_malloc(sizeof(trm_get_info_input_type));
  trm_get_info_return_type *output = (trm_get_info_return_type*)cm_mem_malloc(sizeof(trm_get_info_return_type));

  if(input != NULL &&
     output != NULL &&
     cmph_is_msim())
  {
    /* Query TRM for fallback state
    */
    input->client_id = TRM_CM;
    input->info_type = TRM_IDLE_COLL_INFO;
    input->input_data.idle_coll_info.action = TRM_IDLE_COLL_ACTION_FALLBACK;
    input->input_data.idle_coll_info.asid = SYS_MODEM_AS_ID_MAX;
    
    trm_get_info(input, output);

    if(output->info_type == TRM_IDLE_COLL_INFO &&
       output->info.idle_coll_info.action_info.action == TRM_IDLE_COLL_ACTION_FALLBACK &&
       output->info.idle_coll_info.data.idle_fallback_data.fallback_type != TRM_FALLBACK_NONE &&
       output->info.idle_coll_info.data.idle_fallback_data.fallback_type != TRM_FALLBACK_MAX)
    {
      ret = TRUE;
    }
  }

  if(input != NULL)
  {
    cm_mem_free(input);
  }

  if(output != NULL)
  {
    cm_mem_free(output);
  }

  return ret;
}

/*===========================================================================

FUNCTION cmph_map_slot_id_to_asubs_id

DESCRIPTION
  Maps MMGSDI slot id to asubs id.
  
===========================================================================*/
sys_modem_as_id_e_type  cmph_map_slot_id_to_asubs_id(
  mmgsdi_slot_id_enum_type  slot_id
)
{
  int i = 0;

  for(i = 0; cmutil_is_as_id_valid(i); i++)
  {
    cmph_sub_info_s_type *ph_sub_ptr = cmph_get_sub_ptr(i);

    if(ph_sub_ptr != NULL &&
       (ph_sub_ptr->slot_id == MMGSDI_SLOT_1 ||
        ph_sub_ptr->slot_id == MMGSDI_SLOT_2) &&
       ph_sub_ptr->slot_id == slot_id)
    {
      return (sys_modem_as_id_e_type)i;
    }
  }

  return SYS_MODEM_AS_ID_NONE;
}

/*==========================================================================

FUNCTION cmph_resume_ps_on_non_dds

DESCRIPTION
  Resume PS on non DDS sub if it is needed

RETURN VALUE
  none

DEPENDENCIES
  None

===========================================================================*/
void cmph_resume_ps_on_non_dds(void)
{
  cmph_s_type  *ph_ptr = cmph_ptr();
  cm_call_cmd_s_type          *call_cmd_ptr;
  cm_call_cmd_info_s_type     *cmd_info_ptr;
  sys_modem_as_id_e_type    non_dds_sub = (ph_ptr->device_prop.msim_prop.default_data_subs == SYS_MODEM_AS_ID_1)? SYS_MODEM_AS_ID_2 :SYS_MODEM_AS_ID_1;
  cmph_sub_info_s_type *ph_sub_ptr = cmph_get_sub_ptr(non_dds_sub);
    
  if (ph_sub_ptr == NULL)
  {
    return;
  }

  if (!ph_sub_ptr->reject_ps_activity)
  {
    return;
  }

  ph_sub_ptr->reject_ps_activity = FALSE;


  call_cmd_ptr = cm_cmd_alloc_call_init();

  if(call_cmd_ptr == NULL)
  {
    sys_err_fatal_null_ptr_exception();
    return;
  }

  /* Get a reference to command information.
  */
  cmd_info_ptr = CMD_INFO_PTR( call_cmd_ptr );

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* Copy command header fields.
  */
  call_cmd_ptr->cmd_cb_func          = NULL;
  call_cmd_ptr->data_block_ptr       = NULL;
  call_cmd_ptr->client_id            = CM_CLIENT_ID_ANONYMOUS;
  call_cmd_ptr->cmd                  = CM_CALL_CMD_DATA_ACTIVITY;
  call_cmd_ptr->cmd_subs             = non_dds_sub;

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* Copy command information fields.
  */
  cmd_info_ptr->data_activity_info.asubs_id = non_dds_sub;
  cmd_info_ptr->data_activity_info.data_activity = SYS_DATA_ACTIVITY_ON_DEMAND_START;

  cmcall_cmd_proc_data_activity(call_cmd_ptr);

  cm_mem_free(call_cmd_ptr);
}

