/*===========================================================================

FUNCTION cmph_get_emerg_pending_sub

DESCRIPTION
  Return the pending emergency sub.

RETURN VALUE
  sys_modem_as_id_e_type
  
===========================================================================*/
sys_modem_as_id_e_type  cmph_get_emerg_pending_sub(void)
{
  if (cmph_is_emerg_pending())
  {
    return (cmph_ptr()->device_prop.ph_oprt_mode.emerg_pending_info.asubs_id);
  }

  return SYS_MODEM_AS_ID_NONE;
} 

/*===========================================================================

FUNCTION cmph_is_emerg_pending_enabled

DESCRIPTION
  Check if the online emergency pending feature is enabled.

RETURN VALUE
  Boolean
  
===========================================================================*/
boolean cmph_is_emerg_pending_enabled(void)
{
  return cmph_ptr()->device_prop.ph_oprt_mode.emerg_pending_info.enabled;
}

/*===========================================================================

FUNCTION cmph_update_emerg_pending

DESCRIPTION
  Set state for online emergency pending.

RETURN VALUE
  None
  
===========================================================================*/
void cmph_update_emerg_pending(
  cm_emerg_pending_info_s_type  info
)
{
  if (!cmph_is_emerg_pending_enabled())
  {
    return;
  }

  if (cmph_ptr()->device_prop.ph_oprt_mode.emerg_pending_info.state == info.state)
  {
    return;
  }

  CM_MSG_HIGH_3("E911_PENDING: UPDATE: state %d->%d, sub %d",
                   cmph_ptr()->device_prop.ph_oprt_mode.emerg_pending_info.state,
                   info.state,
                   info.asubs_id);
  cmph_ptr()->device_prop.ph_oprt_mode.emerg_pending_info.state = info.state;

  if (cmph_is_emerg_pending())
  {
    if (cmph_is_ssim())
    {
      cmph_ptr()->device_prop.ph_oprt_mode.emerg_pending_info.asubs_id 
        = SYS_MODEM_AS_ID_1;
    }
    else
    {
      cmph_ptr()->device_prop.ph_oprt_mode.emerg_pending_info.asubs_id 
        = info.asubs_id;
    }
  }
  else
  {
    cmph_ptr()->device_prop.ph_oprt_mode.emerg_pending_info.asubs_id 
      = SYS_MODEM_AS_ID_NONE;
  }
}

/*===========================================================================

FUNCTION cmph_delete_emerg_pending_obj

DESCRIPTION
  Delete the online pending emergency call orig params.
  This is used when dial call is received or ext e911 enter. The function only removes obj and not
  force call end to SD as the actual emergency call will create new emergency object and force
  preference.

RETURN VALUE
  None
  
===========================================================================*/
void cmph_delete_emerg_pending_obj(void)
{
  mm_sub_stk_id_s_type       local_mm_id;
  cm_emerg_pending_info_s_type emerg_pending_info;
  cm_call_id_type            call_id;
  boolean                    top_ptr_changed;
  cm_emerg_pending_info_s_type exit_info;
  
  if (!cmph_is_emerg_pending())
  {
    return;
  }

  /* On receiving dial call request or emergency enter for EXT E911
  ** de-allocate call_id and delete orig param entry if in e911 pending state
  ** Following this the dialled E911 call preferences will be forced.
  */

  emerg_pending_info = cmph_get_emerg_pending_info();
  local_mm_id.asubs_id = emerg_pending_info.asubs_id;
  local_mm_id.stk_id = MM_STACK_0;

  /* deallocate the call ID */
  call_id = cmcall_get_emerg_call_id(local_mm_id.asubs_id);

  CM_MSG_HIGH_2("E911_PENDING: DELETE_OBJ: call_id %d, sub %d",
                    call_id,
                    local_mm_id.asubs_id);

  for( local_mm_id.stk_id = MM_STACK_0;
       local_mm_id.stk_id < cmtask_get_num_stacks(local_mm_id.asubs_id);
       local_mm_id.stk_id++)
  {
    cmph_remove_orig_mode_with_act_id(local_mm_id,
                                      (cm_act_id_type)call_id,
                                      &top_ptr_changed);
  }

  cm_call_id_deallocate (call_id);
  
  exit_info.state = CM_E911_PENDING_STATE_OFF;
  exit_info.asubs_id = SYS_MODEM_AS_ID_NONE;
  
  cmph_update_emerg_pending(exit_info);
} 

/*===========================================================================

FUNCTION cmph_update_orig_param_emerg_pending

DESCRIPTION
  Process emerg pending state upon updating orig params.

RETURN VALUE
  None
  
===========================================================================*/
void cmph_update_orig_param_emerg_pending(void)
{
  if (cmph_is_emerg_pending())
  {
    cm_emerg_pending_info_s_type exit_info;
    
    exit_info.state = CM_E911_PENDING_STATE_OFF;
    exit_info.asubs_id = SYS_MODEM_AS_ID_NONE;  
    cmph_update_emerg_pending(exit_info);
  }
}

/*===========================================================================

FUNCTION cmph_exit_emerg_pending_st

DESCRIPTION
  Exit online emergency pending state.
  This is for abnormal cases. The function removes emerg obj and force end to SD.
  - no dial call request but oprt mode is changed to NON online or online with emerg pending 
    state OFF. 
  - dial call request encounters an error.
  - emerg enter in wrong state.

RETURN VALUE
  None
  
===========================================================================*/
void cmph_exit_emerg_pending_st(void)
{
  mm_sub_stk_id_s_type local_mm_id;
  cm_emerg_pending_info_s_type e911_pending_info;
  cm_call_id_type call_id;

  /* Exit E911 pending state if
  ** 1. Any oprt mode other than ONLINE is received or
  ** 2. ONLINE with pending state OFF is received (user disconnects call 
  **    before dial call request) or
  ** 3. If E911 orig command or Ext E911 enter command returns an error
  ** - Delete the inserted call object
  ** - Remove orig mode from priority queue and unforce preferences.
  ** - Set E911 pending state to OFF
  */
  e911_pending_info = cmph_get_emerg_pending_info();
  local_mm_id.asubs_id = e911_pending_info.asubs_id;

  if (!cmph_is_emerg_pending())
  {
    return;
  }

  /* Deallocate the call ID and 
  **Remove object from priority queue and unforce the call preferences
  */
  call_id = cmcall_get_emerg_call_id(local_mm_id.asubs_id);

  CM_MSG_HIGH_2("E911_PENDING: EXIT: call_id %d, sub %d",
                    call_id,
                    local_mm_id.asubs_id);
                           
  for( local_mm_id.stk_id = MM_STACK_0;
       local_mm_id.stk_id < cmtask_get_num_stacks(local_mm_id.asubs_id);
       local_mm_id.stk_id++)
  {
    (void) cmph_update_orig_param((cm_act_id_type) call_id,
                                  local_mm_id,
                                  CM_ACT_UPDATE_REAS_ACT_END);
  }

  cm_call_id_deallocate(call_id);

  #ifdef FEATURE_MMODE_DUAL_SIM
  if(cmph_is_dsds())
  {
    cmmsimc_suspend_or_resume_other_subs(local_mm_id.asubs_id, FALSE);
  }
  #endif
}

/*===========================================================================

FUNCTION cmph_exit_emerg_pending_st_chk

DESCRIPTION
  Exit pending emergency state if UE changes oprt mode to non ONLINE, or pending state is
  OFF.

RETURN VALUE
  TRUE if this is an online request to exit emegency pending state.  
  
===========================================================================*/
boolean cmph_exit_emerg_pending_st_chk(
  cm_ph_cmd_s_type  *ph_cmd_ptr
)
{
  cmph_s_type *ph_ptr = cmph_ptr();
  cm_ph_cmd_info_s_type *cmd_info_ptr = NULL;

  if(ph_cmd_ptr == NULL)
  {
    return FALSE;
  }

  cmd_info_ptr = CMD_INFO_PTR( ph_cmd_ptr );

  /* Exit E911 pending state if
  ** 1. Any oprt mode other than ONLINE is received or
  ** 2. ONLINE with pending state OFF is received (user disconnects call 
  **    before dial call request)
  */
  if (cmph_is_emerg_pending()
     &&
      ((ph_ptr->device_prop.ph_oprt_mode.oprt_mode == SYS_OPRT_MODE_ONLINE &&
        cmd_info_ptr->oprt_mode != SYS_OPRT_MODE_ONLINE)
        ||
       (cmd_info_ptr->oprt_mode == SYS_OPRT_MODE_ONLINE &&
        cmd_info_ptr->emerg_pending_info.state == CM_E911_PENDING_STATE_OFF)
      )
  )
  {
    cmph_exit_emerg_pending_st();
    
    /* Return TRUE only when ONLINE with E911_PENDING_OFF is received
    ** as this ONLINE should not be processed and will only be used 
    ** to exit pending emergency state
    ** If exiting pending E911 state due to oprt_mode change return FALSE
    ** so that oprt_mode change can be processed
    */
    if (cmd_info_ptr->oprt_mode == SYS_OPRT_MODE_ONLINE)
    {
      return TRUE;
    }
  }
  return FALSE;
}

/*===========================================================================

FUNCTION cmph_force_emerg_pending

DESCRIPTION
  Process online mode with pending E911 call and force preference to MMOC.

RETURN VALUE
  None

===========================================================================*/
void cmph_force_emerg_pending(void)
{
  cm_call_id_type call_id;
  cmph_s_type *ph_ptr  = cmph_ptr();
  cmcall_s_type *call_ptr = NULL;
  sys_modem_as_id_e_type emerg_sub = cmph_get_emerg_pending_info().asubs_id;
  cm_e911_pending_state_e_type state = cmph_get_emerg_pending_info().state;

  if (!cmph_is_emerg_pending()) return;

  /* While entering E911 pending state:
  ** - For MSIM, suspend the sub on which E911 is not originated
  ** - Insert a call object to help with utility functions check for 
  **   emergency calls
  ** - Insert orig mode in priority queue
  ** - Suspend PM
  */

  #ifdef FEATURE_MMODE_DUAL_SIM
  if (cmph_is_dsds() &&
     ph_ptr->device_prop.msim_prop.internal_standby_pref 
             == SYS_MODEM_DS_PREF_DUAL_STANDBY)
  {
    /* Suspend the non e911 sub */
    cmmsimc_suspend_or_resume_other_subs(
            emerg_sub,
            TRUE);
  }
  #endif
  
  call_id = cm_call_id_allocate_new(FALSE);
  if ((call_ptr = cmcall_ptr(call_id)) == NULL)
  {
    CM_MSG_HIGH_0("call_ptr_NULL");
    return;
  }
  
  cmcall_set_type(call_ptr, CM_CALL_TYPE_EMERGENCY);
  call_ptr->mm_id.asubs_id = emerg_sub;

  CM_MSG_HIGH_2("E911_PENDING: FORCE: call_id %d, sub %d", 
                    call_id,
                    emerg_sub);
                    
  cmph_force_pref_on_the_fly_by_call_type(
          CM_CALL_TYPE_EMERGENCY,
          CM_SRV_TYPE_AUTOMATIC,
          CM_MODE_PREF_NONE,
          emerg_sub,
          (cm_act_id_type) call_id);

  cmpmprx_notify_emg_call_start();
}

/*===========================================================================

FUNCTION cmph_oprt_mode_emerg_pending_check

DESCRIPTION
  Check parameter errors for operating mode setting command

RETURN VALUE
  CM_PH_CMD_ERR_NONE if no parameter related errors,
  otherwise specific cm_call_cmd_err_e_type.
  
===========================================================================*/
cm_ph_cmd_err_e_type  cmph_oprt_mode_emerg_pending_check(
  cm_ph_cmd_s_type  *ph_cmd_ptr
)
{
  cm_ph_cmd_info_s_type *cmd_info_ptr = NULL;
  cm_ph_cmd_err_e_type cmd_err = CM_PH_CMD_ERR_NOERR;
  cmph_s_type *ph_ptr = cmph_ptr();

  CM_ASSERT(ph_cmd_ptr != NULL);
  cmd_info_ptr = CMD_INFO_PTR(ph_cmd_ptr);

  /* Return error if 
  ** 1) ONLINE with pending state TRUE is received after ONLINE 
  **    with no pending E911 call
  ** 2) ONLINE with pending E911 call received on the inactive SUB
  */
  if (cmd_info_ptr->oprt_mode == SYS_OPRT_MODE_ONLINE 
     && 
     cmd_info_ptr->emerg_pending_info.state == CM_E911_PENDING_STATE_ON 
     && 
     ((ph_ptr->device_prop.ph_oprt_mode.oprt_mode == SYS_OPRT_MODE_ONLINE &&
       ph_ptr->device_prop.ph_oprt_mode.emerg_pending_info.state 
            == CM_E911_PENDING_STATE_OFF)
        || 
       !(ph_ptr->device_prop.msim_prop.active_subs 
            & BM(cmd_info_ptr->emerg_pending_info.asubs_id))
     )
  )
  {
    cmd_err = CM_PH_CMD_ERR_OPRT_MODE_S;
    CM_MSG_HIGH_5("E911_PENDING: ERROR: oprt_mode %d, state %d, current state %d, sub %d, active_subs %d",
                        cmd_info_ptr->oprt_mode,
                        cmd_info_ptr->emerg_pending_info.state, 
                        ph_ptr->device_prop.ph_oprt_mode.emerg_pending_info.state,
                        cmd_info_ptr->emerg_pending_info.asubs_id,
                        ph_ptr->device_prop.msim_prop.active_subs);
  }

  return cmd_err;
}

/*===========================================================================

FUNCTION cmph_oprt_mode_is_dup_check

DESCRIPTION
  Check if oprt_mode command is duplicate

RETURN VALUE
  TRUE if this is a duplicate oprt_mode command.
  
===========================================================================*/
boolean cmph_oprt_mode_is_dup_check(
  cm_ph_cmd_s_type     *ph_cmd_ptr
)
{
  cm_ph_cmd_info_s_type *cmd_info_ptr = NULL;
  cmph_s_type *ph_ptr  = cmph_ptr();

  if (ph_cmd_ptr == NULL)
  {
    return FALSE;
  }

  cmd_info_ptr = CMD_INFO_PTR(ph_cmd_ptr);

  /* Include E911 pending info in check for ONLINE->ONLINE duplicate 
   * mode change
   */
  if (cmd_info_ptr->oprt_mode == SYS_OPRT_MODE_ONLINE &&
     cmd_info_ptr->oprt_mode == ph_ptr->device_prop.ph_oprt_mode.oprt_mode &&
     cmd_info_ptr->emerg_pending_info.state 
           == ph_ptr->device_prop.ph_oprt_mode.emerg_pending_info.state
  )
  {
    /* Check for subs_id match only when in E911 pending state. Else subs_id 
     * is ignored for exit E911 pending state
     */
    if (cmd_info_ptr->emerg_pending_info.state != CM_E911_PENDING_STATE_ON 
       ||
       (cmd_info_ptr->emerg_pending_info.state == CM_E911_PENDING_STATE_ON &&
        cmd_info_ptr->emerg_pending_info.asubs_id
             == ph_ptr->device_prop.ph_oprt_mode.emerg_pending_info.asubs_id
       )
    )
    {
      sys_modem_as_id_e_type sub_w_1x = cmmsc_get_1x_sub();
      cmph_sub_info_s_type *ph_sub_ptr = cmph_get_sub_ptr(sub_w_1x);

      /* For ONLINE - ONLINE transition, be sure to set the rtre information */
      if (ph_sub_ptr)
      {
        ph_cmd_ptr->info.rtre_control = ph_sub_ptr->rtre_control;
        ph_cmd_ptr->info.rtre_config = ph_sub_ptr->rtre_config;
      }

      CM_MSG_HIGH_4("E911_PENDING: dup online cmd, ph %d %d, cmd %d %d", 
                        ph_ptr->device_prop.ph_oprt_mode.emerg_pending_info.state,
                        ph_ptr->device_prop.ph_oprt_mode.emerg_pending_info.asubs_id,
                        cmd_info_ptr->emerg_pending_info.state,
                        cmd_info_ptr->emerg_pending_info.asubs_id);
      return TRUE;
    }
  }
  return FALSE;
}

/*===========================================================================

FUNCTION cmph_skip_orig_proc

DESCRIPTION
  Check if orig proc is to skipped for the call id. If online emergency pending is true, the call id
  is allocated but there is no actual dial call request yet.  CM does not need to process the 
  call.

RETURN VALUE
  Boolean
  
===========================================================================*/
boolean cmph_skip_orig_proc(
  cmcall_s_type  *call_ptr
)
{
  if (call_ptr->call_type == CM_CALL_TYPE_EMERGENCY &&
     cmph_get_emerg_pending_sub() == call_ptr->mm_id.asubs_id
  )
  {
    return TRUE;
  }

  return FALSE;
}


